t yet supported on safari.\\n                        fetch(`/web/webclient/translations/${cache_hashes.translations}?lang=${user_context.lang}`);\\n                    }\\n                </script>\\n                <t t-if=\\"request.httprequest.cookies.get('color_scheme') == 'dark'\\">\\n                    <t t-call-assets=\\"web.dark_mode_assets_common\\" t-js=\\"false\\"/>\\n                    <t t-call-assets=\\"web.dark_mode_assets_backend\\" t-js=\\"false\\"/>\\n                </t>\\n                <t t-else=\\"\\">\\n                    <t t-call-assets=\\"web.assets_common\\" t-js=\\"false\\"/>\\n                    <t t-call-assets=\\"web.assets_backend\\" t-js=\\"false\\"/>\\n                </t>\\n                <t t-call-assets=\\"web.assets_common\\" t-css=\\"false\\"/>\\n                <t t-call-assets=\\"web.assets_backend\\" t-css=\\"false\\"/>\\n                <t t-call-assets=\\"web.assets_backend_prod_only\\" t-css=\\"false\\"/>\\n                <t t-call=\\"web.conditional_assets_tests\\"/>\\n            </t>\\n            <t t-set=\\"head\\" t-value=\\"head_web + (head or '')\\"/>\\n            <t t-set=\\"body_classname\\" t-value=\\"'o_web_client'\\"/>\\n        </t>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="web.webclient_bootstrap">\n        <t t-call="web.layout">\n            <t t-set="head_web">\n                <meta name="viewport" content="width=device-width, initial-scale=1, user-scalable=no"/>\n                <!-- Chrome, Firefox OS and Opera -->\n                <meta name="theme-color" content="#875A7B"/>\n                <link rel="icon" sizes="192x192" href="/web/static/img/mobile-icons/android-192x192.png"/>\n\n                <!-- iOS Safari -->\n                <meta name="apple-mobile-web-app-capable" content="yes"/>\n                <meta name="apple-mobile-web-app-status-bar-style" content="black"/>\n                <link rel="apple-touch-icon" href="/web/static/img/mobile-icons/apple-152x152.png"/>\n\n                <!-- Windows Phone -->\n                <meta name="msapplication-navbutton-color" content="#875A7B"/>\n                <meta name="msapplication-TileColor" content="#875A7B"/>\n                <meta name="msapplication-TileImage" content="/web/static/img/mobile-icons/windows-144x144.png"/>\n\n                <script type="text/javascript">\n                    odoo.__session_info__ = <t t-out="json.dumps(session_info)"/>;\n                    odoo.reloadMenus = () =&gt; fetch(`/web/webclient/load_menus/${odoo.__session_info__.cache_hashes.load_menus}`).then(res =&gt; res.json());\n                    odoo.loadMenusPromise = odoo.reloadMenus();\n                    // Block to avoid leaking variables in the script scope\n                    {\n                        const { user_context,  cache_hashes } = odoo.__session_info__;\n                        // Prefetch translations to speedup webclient. This is done in JS because link rel="prefetch"\n                        // is not yet supported on safari.\n                        fetch(`/web/webclient/translations/${cache_hashes.translations}?lang=${user_context.lang}`);\n                    }\n                </script>\n                <t t-if="request.httprequest.cookies.get('color_scheme') == 'dark'">\n                    <t t-call-assets="web.dark_mode_assets_common" t-js="false"/>\n                    <t t-call-assets="web.dark_mode_assets_backend" t-js="false"/>\n                </t>\n                <t t-else="">\n                    <t t-call-assets="web.assets_common" t-js="false"/>\n                    <t t-call-assets="web.assets_backend" t-js="false"/>\n                </t>\n                <t t-call-assets="web.assets_common" t-css="false"/>\n                <t t-call-assets="web.assets_backend" t-css="false"/>\n                <t t-call-assets="web.assets_backend_prod_only" t-css="false"/>\n                <t t-call="web.conditional_assets_tests"/>\n            </t>\n            <t t-set="head"