192	16	\N	1	1	Report layout	\N	web.report_layout	qweb	web/views/report_templates.xml	\N	primary	{"en_US": "<t name=\\"Report layout\\" t-name=\\"web.report_layout\\">&lt;!DOCTYPE html&gt;\\n        <html t-att-lang=\\"lang and lang.replace('_', '-')\\" t-att-data-report-margin-top=\\"data_report_margin_top\\" t-att-data-report-header-spacing=\\"data_report_header_spacing\\" t-att-data-report-dpi=\\"data_report_dpi\\" t-att-data-report-landscape=\\"data_report_landscape\\" t-att-web-base-url=\\"web_base_url\\">\\n            <head>\\n                <meta charset=\\"utf-8\\"/>\\n                <meta name=\\"viewport\\" content=\\"initial-scale=1\\"/>\\n                <title><t t-esc=\\"title or 'Odoo Report'\\"/></title>\\n                <t t-call-assets=\\"web.report_assets_common\\" t-js=\\"false\\"/>\\n                <!--The following is kind of a hack-->\\n                <!--in an iframe, we don't want the session to perform qweb_templates rpc-->\\n                <script type=\\"text/javascript\\">\\n                    window.odoo = {};\\n                    window.odoo.__session_info__ = {is_report: true};\\n                </script>\\n                <t t-call-assets=\\"web.assets_common\\" t-css=\\"false\\"/>\\n                <t t-call-assets=\\"web.report_assets_common\\" t-css=\\"false\\"/>\\n            </head>\\n            <body t-att-class=\\"'container' if not full_width else 'container-fluid'\\">\\n                <div id=\\"wrapwrap\\">\\n                    <main>\\n                        <t t-out=\\"0\\"/>\\n                    </main>\\n                </div>\\n            </body>\\n        </html>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Report layout" t-name="web.report_layout">&lt;!DOCTYPE html&gt;\n        <html t-att-lang="lang and lang.replace('_', '-')" t-att-data-report-margin-top="data_report_margin_top" t-att-data-report-header-spacing="data_report_header_spacing" t-att-data-report-dpi="data_report_dpi" t-att-data-report-landscape="data_report_landscape" t-att-web-base-url="web_base_url">\n            <head>\n                <meta charset="utf-8"/>\n                <meta name="viewport" content="initial-scale=1"/>\n                <title><t t-esc="title or 'Odoo Report'"/></title>\n                <t t-call-assets="web.report_assets_common" t-js="false"/>\n                <!--The following is kind of a hack-->\n                <!--in an iframe, we don't want the session to perform qweb_templates rpc-->\n                <script type="text/javascript">\n                    window.odoo = {};\n                    window.odoo.__session_info__ = {is_report: true};\n                </script>\n                <t t-call-assets="web.assets_common" t-css="false"/>\n                <t t-call-assets="web.report_assets_common" t-css="false"/>\n            </head>\n            <body t-att-class="'container' if not full_width else 'container-fluid'">\n                <div id="wrapwrap">\n                    <main>\n                        <t t-out="0"/>\n                    </main>\n                </div>\n            </body>\n        </html>\n    </t>\n\n    	f	t	2023-11-01 05:00:37.875455	2023-11-01 05:00:37.875455	\N
193	16	\N	1	1	Report layout	\N	web.report_preview_layout	qweb	web/views/report_templates.xml	\N	primary	{"en_US": "<t name=\\"Report layout\\" t-name=\\"web.report_preview_layout\\">&lt;!DOCTYPE html&gt;\\n        <html t-att-lang=\\"lang and lang.replace('_', '-')\\" t-att-data-report-margin-top=\\"data_report_margin_top\\" t-att-data-report-header-spacing=\\"data_report_header_spacing\\" t-att-data-report-dpi=\\"data_report_dpi\\" t-att-data-report-landscape=\\"data_report_landscape\\" t-att-web-base-url=\\"web_base_url\\">\\n            <head>\\n                <meta charset=\\"utf-8\\"/>\\n                <meta name=\\"viewport\\" content=\\"initial-scale=1\\"/>\\n                <title><t t-esc=\\"title or 'Odoo Report'\\"/></title>\\n                <t t-call-assets=\\"web.report_assets_common\\" t-js=\\"false\\"/>\\n                <t t-call-assets=\\"web.assets_common\\" t-css=\\"false\\"/>\\n                <style>\\n                    <t t-out=\\"preview_css\\"/>\\n\\n                    /**\\n                        Some css is overridden as it doesn't work properly in the preview.\\n                        Before generating 'real' reports, a lot of processing is applied. It is therefore quite\\n                        complicated to have an almost exact replica of the pdf report.\\n                        This changes down here are hacks to make the preview look as good as possible.\\n                    **/\\n\\n                    /** The footers are not at the bottom of the page, so we push them down. **/\\n                    .o_background_footer, .o_standard_footer, .o_boxed_footer, .o_clean_footer {\\n                        position: absolute;\\n                        bottom: 0;\\n                        left:50px;\\n                        right:50px;\\n                        font-size: 0.8rem\\n                    }\\n                    /** Avoid image overflowing and creating a scrollbar **/\\n                    .o_background_header {\\n                        min-width: initial !important;\\n                    }\\n\\n                    /** This rule is overridden in web/report.scss to hack around whtml2pdf\\n                        Simply set it to its default value so it works properly in preview **/\\n                    .col-auto{\\n                        -webkit-box-flex: 0 !important;\\n                        -webkit-flex: 0 0 auto !important;\\n                        flex: 0 0 auto !important;\\n                        width: auto !important;\\n                        max-width: 100% !important;\\n                    }\\n\\n                </style>\\n            </head>\\n            <body t-att-class=\\"'container' if not full_width else 'container-fluid'\\" style=\\"overflow:hidden\\">\\n                <div id=\\"wrapwrap\\">\\n                        <t t-out=\\"0\\"/>\\n                </div>\\n            </body>\\n        </html>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Report layout" t-name="web.report_preview_layout">&lt;!DOCTYPE html&gt;\n        <html t-att-lang="lang and lang.replace('_', '-')" t-att-data-report-margin-top="data_report_margin_top" t-att-data-report-header-spacing="data_report_header_spacing" t-att-data-report-dpi="data_report_dpi" t-att-data-report-landscape="data_report_landscape" t-att-web-base-url="web_base_url">\n            <head>\n                <meta charset="utf-8"/>\n                <meta name="viewport" content="initial-scale=1"/>\n                <title><t t-esc="title or 'Odoo Report'"/></title>\n                <t t-call-assets="web.report_assets_common" t-js="false"/>\n                <t t-call-assets="web.assets_common" t-css="false"/>\n                <style>\n                    <t t-out="preview_css"/>\n\n                    /**\n                        Some css is overridden as it doesn't work properly in the preview.\n                        Before generating 'real' reports, a lot of processing is applied. It is therefore quite\n                        complicated to have an almost exact replica of the pdf report.\n                        This changes down here are hacks to make the preview look as good as possible.\n                    **/\n\n                    /** The footers are not at the bottom of the page, so we push them down. **/\n                    .o_background_footer, .o_standard_footer, .o_boxed_footer, .o_clean_footer {\n                        position: absolute;\n                        bottom: 0;\n                        left:50px;\n                        right:50px;\n                        font-size: 0.8rem\n                    }\n                    /** Avoid image overflowing and creating a scrollbar **/\n                    .o_background_header {\n                        min-width: initial !important;\n                    }\n\n                    /** This rule is overridden in web/report.scss to hack around whtml2pdf\n                        Simply set it to its default value so it works properly in preview **/\n                    .col-auto{\n                        -webkit-box-flex: 0 !important;\n                        -webkit-flex: 0 0 auto !important;\n                        flex: 0 0 auto !important;\n                        width: auto !important;\n                        max-width: 100% !important;\n                    }\n\n                </style>\n            </head>\n            <body t-att-class="'container' if not full_width else 'container-fluid'" style="overflow:hidden">\n                <div id="wrapwrap">\n                        <t t-out="0"/>\n                </div>\n            </body>\n        </html>\n    </t>\n\n    	f	t	2023-11-01 05:00:37.875455	2023-11-01 05:00:37.875455	\N
