526	16	\N	1	1	report_picking	\N	stock.report_picking	qweb	stock/report/report_stockpicking_operations.xml	\N	primary	{"en_US": "<t t-name=\\"stock.report_picking\\">\\n            <t t-call=\\"web.html_container\\">\\n                <t t-foreach=\\"docs\\" t-as=\\"o\\">\\n                    <t t-call=\\"web.external_layout\\">\\n                        <div class=\\"page\\">\\n                            <div class=\\"row justify-content-end mb16\\">\\n                                <div class=\\"col-4\\" name=\\"right_box\\">\\n                                    <div t-field=\\"o.name\\" t-options=\\"{'widget': 'barcode', 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;'}\\"/>\\n                                </div>\\n                            </div>\\n                            <div class=\\"row\\">\\n                                <div class=\\"col-6\\" name=\\"div_outgoing_address\\">\\n                                    <div t-if=\\"o.should_print_delivery_address()\\">\\n                                        <span><strong>Delivery Address:</strong></span>\\n                                        <div t-field=\\"o.move_ids[0].partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                                    </div>\\n                                    <div t-elif=\\"o.picking_type_id.code != 'internal' and o.picking_type_id.warehouse_id.partner_id\\">\\n                                        <span><strong>Warehouse Address:</strong></span>\\n                                        <div t-field=\\"o.picking_type_id.warehouse_id.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                                    </div>\\n                                </div>\\n                                <div class=\\"col-5 offset-1\\" name=\\"div_incoming_address\\">\\n                                    <t t-set=\\"show_partner\\" t-value=\\"False\\"/>\\n                                    <div t-if=\\"o.picking_type_id.code=='incoming' and o.partner_id\\">\\n                                        <span><strong>Vendor Address:</strong></span>\\n                                        <t t-set=\\"show_partner\\" t-value=\\"True\\"/>\\n                                    </div>\\n                                    <div t-if=\\"o.picking_type_id.code=='internal' and o.partner_id\\">\\n                                        <span><strong>Warehouse Address:</strong></span>\\n                                        <t t-set=\\"show_partner\\" t-value=\\"True\\"/>\\n                                    </div>\\n                                    <div t-if=\\"o.picking_type_id.code=='outgoing' and o.partner_id and o.partner_id != o.partner_id.commercial_partner_id\\">\\n                                        <span><strong>Customer Address:</strong></span>\\n                                        <t t-set=\\"show_partner\\" t-value=\\"True\\"/>\\n                                    </div>\\n                                    <div t-if=\\"show_partner\\" name=\\"partner_header\\">\\n                                        <div t-field=\\"o.partner_id.commercial_partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                                    </div>\\n                                </div>\\n                            </div>\\n                            <br/>\\n                            <h1 t-field=\\"o.name\\" class=\\"mt0\\"/>\\n                            <div class=\\"row mt48 mb32\\">\\n                                <div t-if=\\"o.origin\\" class=\\"col-auto\\" name=\\"div_origin\\">\\n                                    <strong>Order:</strong>\\n                                    <p t-field=\\"o.origin\\"/>\\n                                </div>\\n                                <div class=\\"col-auto\\" name=\\"div_state\\">\\n                                    <strong>Status:</strong>\\n                                    <p t-field=\\"o.state\\"/>\\n                                </div>\\n                                <div class=\\"col-auto\\" name=\\"div_sched_date\\">\\n                                    <strong>Scheduled Date:</strong>\\n                                    <p t-field=\\"o.scheduled_date\\"/>\\n                                </div>\\n                            </div>\\n                            <table class=\\"table table-sm\\" t-if=\\"o.move_line_ids and o.move_ids_without_package\\">\\n                                <t t-set=\\"has_barcode\\" t-value=\\"any(move_line.product_id and move_line.product_id.sudo().barcode or move_line.package_id for move_line in o.move_line_ids)\\"/>\\n                                <t t-set=\\"has_serial_number\\" t-value=\\"any(move_line.lot_id or move_line.lot_name for move_line in o.move_line_ids)\\" groups=\\"stock.group_production_lot\\"/>\\n                                <thead>\\n                                    <tr>\\n                                        <th name=\\"th_product\\">\\n                                            <strong>Product</strong>\\n                                        </th>\\n                                        <th>\\n                                            <strong>Quantity</strong>\\n                                        </th>\\n                                        <th name=\\"th_from\\" t-if=\\"o.picking_type_id.code != 'incoming'\\" align=\\"left\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <strong>From</strong>\\n                                        </th>\\n                                        <th name=\\"th_to\\" t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <strong>To</strong>\\n                                        </th>\\n                                        <th name=\\"th_serial_number\\" class=\\"text-center\\" t-if=\\"has_serial_number\\">\\n                                           <strong>Lot/Serial Number</strong>\\n                                        </th>\\n                                        <th name=\\"th_barcode\\" class=\\"text-center\\" t-if=\\"has_barcode\\">\\n                                            <strong>Product Barcode</strong>\\n                                        </th>\\n                                    </tr>\\n                                </thead>\\n                                <tbody>\\n                                    <!-- In case you come across duplicated lines, ask NIM or LAP -->\\n                                    <t t-foreach=\\"o.move_line_ids_without_package\\" t-as=\\"ml\\">\\n                                        <tr>\\n                                            <td>\\n                                                <span t-field=\\"ml.product_id.display_name\\"/><br/>\\n                                                <span t-field=\\"ml.product_id.description_picking\\"/>\\n                                            </td>\\n                                            <td>\\n                                                <span t-if=\\"o.state != 'done'\\" t-field=\\"ml.reserved_uom_qty\\"/>\\n                                                <span t-if=\\"o.state == 'done'\\" t-field=\\"ml.qty_done\\"/>\\n                                                <span t-field=\\"ml.product_uom_id\\" groups=\\"uom.group_uom\\"/>\\n                                            </td>\\n                                            <td t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <span t-esc=\\"ml.location_id.display_name\\"/>\\n                                                    <t t-if=\\"ml.package_id\\">\\n                                                        <span t-field=\\"ml.package_id\\"/>\\n                                                    </t>\\n                                            </td>\\n                                            <td t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                                <div>\\n                                                    <span t-field=\\"ml.location_dest_id\\"/>\\n                                                    <t t-if=\\"ml.result_package_id\\">\\n                                                        <span t-field=\\"ml.result_package_id\\"/>\\n                                                    </t>\\n                                                </div>\\n                                            </td>\\n                                            <td class=\\" text-center h6\\" t-if=\\"has_serial_number\\">\\n                                                <div t-if=\\"has_serial_number and (ml.lot_id or ml.lot_name)\\" t-esc=\\"ml.lot_id.name or ml.lot_name\\" t-options=\\"{'widget': 'barcode', 'humanreadable': 1, 'width': 400, 'height': 100, 'img_style': 'width:100%;height:35px;'}\\"/>\\n                                            </td>\\n                                            <td class=\\"text-center\\" t-if=\\"has_barcode\\">\\n                                                <t t-if=\\"product_barcode != ml.product_id.barcode\\">\\n                                                    <span t-if=\\"ml.product_id and ml.product_id.barcode\\">\\n                                                        <div t-field=\\"ml.product_id.barcode\\" t-options=\\"{'widget': 'barcode', 'symbology': 'auto', 'width': 400, 'height': 100, 'quiet': 0, 'img_style': 'height:35px;'}\\"/>\\n                                                    </span>\\n                                                    <t t-set=\\"product_barcode\\" t-value=\\"ml.product_id.barcode\\"/>\\n                                                </t>\\n                                            </td>\\n                                        </tr>\\n                                    </t>\\n                                  </tbody>\\n                            </table>\\n                            <table class=\\"table table-sm\\" t-if=\\"o.package_level_ids and o.picking_type_entire_packs and o.state in ['assigned', 'done']\\">\\n                                <thead>\\n                                    <tr>\\n                                        <th name=\\"th_package\\">Package</th>\\n                                        <th name=\\"th_pko_from\\" t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">From</th>\\n                                        <th name=\\"th_pki_from\\" t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">To</th>\\n                                    </tr>\\n                                </thead>\\n                                <tbody>\\n                                    <tr t-foreach=\\"o.package_level_ids.sorted(key=lambda p: p.package_id.name)\\" t-as=\\"package\\">\\n                                        <t t-set=\\"package\\" t-value=\\"package.with_context(picking_id=o.id)\\"/>\\n                                        <td name=\\"td_pk_barcode\\">\\n                                            <div t-field=\\"package.package_id.name\\" t-options=\\"{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-left: -50px;'}\\"/><br/>\\n                                        </td>\\n                                        <td t-if=\\"o.picking_type_id.code != 'incoming'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <span t-field=\\"package.location_id\\"/>\\n                                        </td>\\n                                        <td t-if=\\"o.picking_type_id.code != 'outgoing'\\" groups=\\"stock.group_stock_multi_locations\\">\\n                                            <span t-field=\\"package.location_dest_id\\"/>\\n                                        </td>\\n                                    </tr>\\n                                </tbody>\\n                            </table>\\n                            <t t-set=\\"no_reserved_product\\" t-value=\\"o.move_ids.filtered(lambda x: x.product_uom_qty != x.reserved_availability and x.move_line_ids and x.state!='done')\\"/>\\n                            <p t-if=\\"o.state in ['draft', 'waiting', 'confirmed'] or no_reserved_product\\"><i class=\\"fa fa-exclamation-triangle\\"/>\\n                                All products could not be reserved. Click on the \\"Check Availability\\" button to try to reserve products.\\n                            </p>\\n                            <p t-field=\\"o.note\\"/>\\n                        </div>\\n                    </t>\\n                </t>\\n            </t>\\n        </t>"}	<?xml version="1.0"?>\n<t t-name="stock.report_picking">\n            <t t-call="web.html_container">\n                <t t-foreach="docs" t-as="o">\n                    <t t-call="web.external_layout">\n                        <div class="page">\n                            <div class="row justify-content-end mb16">\n                                <div class="col-4" name="right_box">\n                                    <div t-field="o.name" t-options="{'widget': 'barcode', 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;'}"/>\n                                </div>\n                            </div>\n                            <div class="row">\n                                <div class="col-6" name="div_outgoing_address">\n                                    <div t-if="o.should_print_delivery_address()">\n                                        <span><strong>Delivery Address:</strong></span>\n                                        <div t-field="o.move_ids[0].partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                                    </div>\n                                    <div t-elif="o.picking_type_id.code != 'internal' and o.picking_type_id.warehouse_id.partner_id">\n                                        <span><strong>Warehouse Address:</strong></span>\n                                        <div t-field="o.picking_type_id.warehouse_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                                    </div>\n                                </div>\n                                <div class="col-5 offset-1" name="div_incoming_address">\n                                    <t t-set="show_partner" t-value="False"/>\n                                    <div t-if="o.picking_type_id.code=='incoming' and o.partner_id">\n                                        <span><strong>Vendor Address:</strong></span>\n                                        <t t-set="show_partner" t-value="True"/>\n                                    </div>\n                                    <div t-if="o.picking_type_id.code=='internal' and o.partner_id">\n                                        <span><strong>Warehouse Address:</strong></span>\n                                        <t t-set="show_partner" t-value="True"/>\n                                    </div>\n                                    <div t-if="o.picking_type_id.code=='outgoing' and o.partner_id and o.partner_id != o.partner_id.commercial_partner_id">\n                                        <span><strong>Customer Address:</strong></span>\n                                        <t t-set="show_partner" t-value="True"/>\n                                    </div>\n                                    <div t-if="show_partner" name="partner_header">\n                                        <div t-field="o.partner_id.commercial_partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                                    </div>\n                                </div>\n                            </div>\n                            <br/>\n                            <h1 t-field="o.name" class="mt0"/>\n                            <div class="row mt48 mb32">\n                                <div t-if="o.origin" class="col-auto" name="div_origin">\n                                    <strong>Order:</strong>\n                                    <p t-field="o.origin"/>\n                                </div>\n                                <div class="col-auto" name="div_state">\n                                    <strong>Status:</strong>\n                                    <p t-field="o.state"/>\n                                </div>\n                                <div class="col-auto" name="div_sched_date">\n                                    <strong>Scheduled Date:</strong>\n                                    <p t-field="o.scheduled_date"/>\n                                </div>\n                            </div>\n                            <table class="table table-sm" t-if="o.move_line_ids and o.move_ids_without_package">\n                                <t t-set="has_barcode" t-value="any(move_line.product_id and move_line.product_id.sudo().barcode or move_line.package_id for move_line in o.move_line_ids)"/>\n                                <t t-set="has_serial_number" t-value="any(move_line.lot_id or move_line.lot_name for move_line in o.move_line_ids)" groups="stock.group_production_lot"/>\n                                <thead>\n                                    <tr>\n                                        <th name="th_product">\n                                            <strong>Product</strong>\n                                        </th>\n                                        <th>\n                                            <strong>Quantity</strong>\n                                        </th>\n                                        <th name="th_from" t-if="o.picking_type_id.code != 'incoming'" align="left" groups="stock.group_stock_multi_locations">\n                                            <strong>From</strong>\n                                        </th>\n                                        <th name="th_to" t-if="o.picking_type_id.code != 'outgoing'" groups="stock.group_stock_multi_locations">\n                                            <strong>To</strong>\n                                        </th>\n                                        <th name="th_serial_number" class="text-center" t-if="has_serial_number">\n                                           <strong>Lot/Serial Number</strong>\n                                        </th>\n                                        <th name="th_barcode" class="text-center" t-if="has_barcode">\n                                            <strong>Product Barcode</strong>\n                                        </th>\n                                    </tr>\n                                </thead>\n                                <tbody>\n                                    <!-- In case you come across duplicated lines, ask NIM or LAP -->\n                                    <t t-foreach="o.move_line_ids_without_package" t-as="ml">\n                                        <tr>\n                                            <td>\n                                                <span t-field="ml.product_id.display_name"/><br/>\n                                                <span t-field="ml.product_id.description_picking"/>\n                                            </td>\n                                            <td>\n                                                <span t-if="o.state != 'done'" t-field="ml.reserved_uom_qty"/>\n                                                <span t-if="o.state == 'done'" t-field="ml.qty_done"/>\n                                                <span t-field="ml.product_uom_id" groups="uom.group_uom"/>\n                                            </td>\n                                            <td t-if="o.picking_type_id.code != 'incoming'" groups="stock.group_stock_multi_locations">\n                                                <span t-esc="ml.location_id.display_name"/>\n                                                    <t t-if="ml.package_id">\n                                                        <span t-field="ml.package_id"/>\n                                                    </t>\n                                            </td>\n                                            <td t-if="o.picking_type_id.code != 'outgoing'" groups="stock.group_stock_multi_locations">\n                                                <div>\n                                                    <span t-field="ml.location_dest_id"/>\n                                                    <t t-if="ml.result_package_id">\n                                                        <span t-field="ml.result_package_id"/>\n                                                    </t>\n                                                </div>\n                                            </td>\n                                            <td class=" text-center h6" t-if="has_serial_number">\n                                                <div t-if="has_serial_number and (ml.lot_id or ml.lot_name)" t-esc="ml.lot_id.name or ml.lot_name" t-options="{'widget': 'barcode', 'humanreadable': 1, 'width': 400, 'height': 100, 'img_style': 'width:100%;height:35px;'}"/>\n                                            </td>\n                                            <td class="text-center" t-if="has_barcode">\n                                                <t t-if="product_barcode != ml.product_id.barcode">\n                                                    <span t-if="ml.product_id and ml.product_id.barcode">\n                                                        <div t-field="ml.product_id.barcode" t-options="{'widget': 'barcode', 'symbology': 'auto', 'width': 400, 'height': 100, 'quiet': 0, 'img_style': 'height:35px;'}"/>\n                                                    </span>\n                                                    <t t-set="product_barcode" t-value="ml.product_id.barcode"/>\n                                                </t>\n                                            </td>\n                                        </tr>\n                                    </t>\n                                  </tbody>\n                            </table>\n                            <table class="table table-sm" t-if="o.package_level_ids and o.picking_type_entire_packs and o.state in ['assigned', 'done']">\n                                <thead>\n                                    <tr>\n                                        <th name="th_package">Package</th>\n                                        <th name="th_pko_from" t-if="o.picking_type_id.code != 'incoming'" groups="stock.group_stock_multi_locations">From</th>\n                                        <th name="th_pki_from" t-if="o.picking_type_id.code != 'outgoing'" groups="stock.group_stock_multi_locations">To</th>\n                                    </tr>\n                                </thead>\n                                <tbody>\n                                    <tr t-foreach="o.package_level_ids.sorted(key=lambda p: p.package_id.name)" t-as="package">\n                                        <t t-set="package" t-value="package.with_context(picking_id=o.id)"/>\n                                        <td name="td_pk_barcode">\n                                            <div t-field="package.package_id.name" t-options="{'widget': 'barcode', 'humanreadable': 1, 'width': 600, 'height': 100, 'img_style': 'width:300px;height:50px;margin-left: -50px;'}"/><br/>\n                                        </td>\n                                        <td t-if="o.picking_type_id.code != 'incoming'" groups="stock.group_stock_multi_locations">\n                                            <span t-field="package.location_id"/>\n                                        </td>\n                                        <td t-if="o.picking_type_id.code != 'outgoing'" groups="stock.group_stock_multi_locations">\n                                            <span t-field="package.location_dest_id"/>\n                                        </td>\n                                    </tr>\n                                </tbody>\n                            </table>\n                            <t t-set="no_reserved_product" t-value="o.move_ids.filtered(lambda x: x.product_uom_qty != x.reserved_availability and x.move_line_ids and x.state!='done')"/>\n                            <p t-if="o.state in ['draft', 'waiting', 'confirmed'] or no_reserved_product"><i class="fa fa-exclamation-triangle"/>\n                                All products could not be reserved. Click on the "Check Availability" button to try to reserve products.\n                            </p>\n                            <p t-field="o.note"/>\n                        </div>\n                    </t>\n                </t>\n            </t>\n        </t>\n        	f	t	2023-11-01 05:02:07.049098	2023-11-01 05:02:07.049098	f
527	16	\N	1	1	report_picking_type_label	\N	stock.report_picking_type_label	qweb	stock/report/report_stockpicking_operations.xml	\N	primary	{"en_US": "<t t-name=\\"stock.report_picking_type_label\\">\\n            <t t-set=\\"title\\">Operation Types</t>\\n            <t t-call=\\"stock.report_generic_barcode\\"/>\\n        </t>"}	<?xml version="1.0"?>\n<t t-name="stock.report_picking_type_label">\n            <t t-set="title">Operation Types</t>\n            <t t-call="stock.report_generic_barcode"/>\n        </t>\n    	f	t	2023-11-01 05:02:07.049098	2023-11-01 05:02:07.049098	f
528	16	\N	1	1	report_delivery_document	\N	stock.report_delivery_document	qweb	stock/report/report_deliveryslip.xml	\N	primary	{"en_US": "<t t-name=\\"stock.report_delivery_document\\">\\n        <t t-call=\\"web.html_container\\">\\n            <t t-call=\\"web.external_layout\\">\\n                <t t-set=\\"o\\" t-value=\\"o.with_context(lang=o._get_report_lang())\\"/>\\n                <t t-set=\\"partner\\" t-value=\\"o.partner_id or (o.move_ids and o.move_ids[0].partner_id) or False\\"/>\\n\\n                <t t-set=\\"address\\">\\n                    <div name=\\"div_outgoing_address\\">\\n                        <div name=\\"outgoing_delivery_address\\" t-if=\\"o.should_print_delivery_address()\\">\\n                            <span><strong>Delivery Address:</strong></span>\\n                            <div t-field=\\"o.move_ids[0].partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                        </div>\\n                        <div name=\\"outgoing_warehouse_address\\" t-elif=\\"o.picking_type_id.code != 'internal' and o.picking_type_id.warehouse_id.partner_id\\">\\n                            <span><strong>Warehouse Address:</strong></span>\\n                            <div t-field=\\"o.picking_type_id.warehouse_id.partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                        </div>\\n                    </div>\\n                </t>\\n                <t t-set=\\"information_block\\">\\n                    <div class=\\"row\\">\\n                        <div class=\\"col-7\\" name=\\"div_incoming_address\\">\\n                            <t t-set=\\"show_partner\\" t-value=\\"False\\"/>\\n                            <div name=\\"vendor_address\\" t-if=\\"o.picking_type_id.code=='incoming' and partner\\">\\n                                <span><strong>Vendor Address:</strong></span>\\n                                <t t-set=\\"show_partner\\" t-value=\\"True\\"/>\\n                            </div>\\n                            <div name=\\"customer_address\\" t-if=\\"o.picking_type_id.code=='outgoing' and partner and partner != partner.commercial_partner_id\\">\\n                                <span><strong>Customer Address:</strong></span>\\n                                <t t-set=\\"show_partner\\" t-value=\\"True\\"/>\\n                            </div>\\n                            <div t-if=\\"show_partner\\" name=\\"partner_header\\">\\n                                <div t-field=\\"partner.commercial_partner_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                            </div>\\n                        </div>\\n                    </div>\\n                </t>\\n                <div class=\\"page\\">\\n                    <h2>\\n                        <span t-field=\\"o.name\\"/>\\n                    </h2>\\n                    <div class=\\"row mt32 mb32\\">\\n                        <div t-if=\\"o.origin\\" class=\\"col-auto\\" name=\\"div_origin\\">\\n                            <strong>Order:</strong>\\n                            <p t-field=\\"o.origin\\"/>\\n                        </div>\\n                        <div t-if=\\"o.state\\" class=\\"col-auto\\" name=\\"div_sched_date\\">\\n                            <strong>Shipping Date:</strong>\\n                            <t t-if=\\"o.state == 'done'\\">\\n                                <p t-field=\\"o.date_done\\"/>\\n                            </t>\\n                            <t t-if=\\"o.state != 'done'\\">\\n                                <p t-field=\\"o.scheduled_date\\"/>\\n                           </t>\\n                        </div>\\n                    </div>\\n                    <table class=\\"table table-sm\\" t-if=\\"o.state!='done'\\" name=\\"stock_move_table\\">\\n                        <thead>\\n                            <tr>\\n                                <th name=\\"th_sm_product\\"><strong>Product</strong></th>\\n                                <th name=\\"th_sm_ordered\\"><strong>Ordered</strong></th>\\n                                <th name=\\"th_sm_quantity\\"><strong>Delivered</strong></th>\\n                            </tr>\\n                        </thead>\\n                        <tbody>\\n                            <t t-set=\\"lines\\" t-value=\\"o.move_ids.filtered(lambda x: x.product_uom_qty)\\"/>\\n                            <tr t-foreach=\\"lines\\" t-as=\\"move\\">\\n                                <td>\\n                                    <span t-field=\\"move.product_id\\"/>\\n                                    <p t-if=\\"move.description_picking != move.product_id.name and move.description_picking != move.product_id.display_name\\">\\n                                        <span t-field=\\"move.description_picking\\"/>\\n                                    </p>\\n                                </td>\\n                                <td>\\n                                    <span t-field=\\"move.product_uom_qty\\"/>\\n                                    <span t-field=\\"move.product_uom\\"/>\\n                                </td>\\n                                <td>\\n                                    <span t-field=\\"move.quantity_done\\"/>\\n                                    <span t-field=\\"move.product_uom\\"/>\\n                                </td>\\n                            </tr>\\n                        </tbody>\\n                    </table>\\n                    <table class=\\"table table-sm mt48\\" t-if=\\"o.move_line_ids and o.state=='done'\\" name=\\"stock_move_line_table\\">\\n                        <t t-set=\\"has_serial_number\\" t-value=\\"False\\"/>\\n                        <t t-set=\\"has_serial_number\\" t-value=\\"o.move_line_ids.mapped('lot_id')\\" groups=\\"stock.group_lot_on_delivery_slip\\"/>\\n                        <thead>\\n                            <tr>\\n                                <th name=\\"th_sml_product\\"><strong>Product</strong></th>\\n                                <t name=\\"lot_serial\\" t-if=\\"has_serial_number\\">\\n                                    <th>\\n                                        Lot/Serial Number\\n                                    </th>\\n                                </t>\\n                                <th name=\\"th_sml_qty_ordered\\" class=\\"text-center\\" t-if=\\"not has_serial_number\\">\\n                                    <strong>Ordered</strong>\\n                                </th>\\n                                <th name=\\"th_sml_quantity\\" class=\\"text-center\\"><strong>Delivered</strong></th>\\n                            </tr>\\n                        </thead>\\n                        <tbody>\\n                        <!-- This part gets complicated with different use cases (additional use cases in extensions of this report):\\n                                1. If serial numbers are used and set to print on delivery slip => print lines as is, otherwise group them by overlapping\\n                                    product + description + uom combinations\\n                                2. If any packages are assigned => split products up by package (or non-package) and then apply use case 1 -->\\n                            <!-- If has destination packages => create sections of corresponding products -->\\n                            <t t-if=\\"o.has_packages\\" name=\\"has_packages\\">\\n                                <t t-set=\\"packages\\" t-value=\\"o.move_line_ids.mapped('result_package_id')\\"/>\\n                                <t t-foreach=\\"packages\\" t-as=\\"package\\">\\n                                    <t t-call=\\"stock.stock_report_delivery_package_section_line\\"/>\\n                                    <t t-set=\\"package_move_lines\\" t-value=\\"o.move_line_ids.filtered(lambda l: l.result_package_id == package)\\"/>\\n                                    <!-- If printing lots/serial numbers => keep products in original lines -->\\n                                    <t t-if=\\"has_serial_number\\">\\n                                        <tr t-foreach=\\"package_move_lines\\" t-as=\\"move_line\\">\\n                                            <t t-call=\\"stock.stock_report_delivery_has_serial_move_line\\"/>\\n                                        </tr>\\n                                    </t>\\n                                    <!-- If not printing lots/serial numbers => merge lines with same product+description+uom -->\\n                                    <t t-else=\\"\\">\\n                                        <t t-set=\\"aggregated_lines\\" t-value=\\"package_move_lines._get_aggregated_product_quantities(strict=True)\\"/>\\n                                        <t t-call=\\"stock.stock_report_delivery_aggregated_move_lines\\"/>\\n                                    </t>\\n                                </t>\\n                                <!-- Make sure we do another section for package-less products if they exist -->\\n                                <t t-set=\\"move_lines\\" t-value=\\"o.move_line_ids.filtered(lambda l: not l.result_package_id)\\"/>\\n                                <t t-set=\\"aggregated_lines\\" t-value=\\"o.move_line_ids._get_aggregated_product_quantities(except_package=True)\\"/>\\n                                <t t-if=\\"move_lines or aggregated_lines\\" name=\\"no_package_move_lines\\">\\n                                    <t t-call=\\"stock.stock_report_delivery_no_package_section_line\\" name=\\"no_package_section\\"/>\\n                                    <t t-if=\\"has_serial_number\\">\\n                                        <tr t-foreach=\\"move_lines\\" t-as=\\"move_line\\">\\n                                            <t t-call=\\"stock.stock_report_delivery_has_serial_move_line\\"/>\\n                                        </tr>\\n                                    </t>\\n                                    <t t-elif=\\"aggregated_lines\\">\\n                                        <t t-call=\\"stock.stock_report_delivery_aggregated_move_lines\\"/>\\n                                    </t>\\n                                </t>\\n                            </t>\\n                            <!-- No destination packages -->\\n                            <t t-else=\\"\\">\\n                                <!-- If printing lots/serial numbers => keep products in original lines -->\\n                                <t t-if=\\"has_serial_number\\">\\n                                    <tr t-foreach=\\"o.move_line_ids\\" t-as=\\"move_line\\">\\n                                        <t t-call=\\"stock.stock_report_delivery_has_serial_move_line\\"/>\\n                                    </tr>\\n                                </t>\\n                                <!-- If not printing lots/serial numbers => merge lines with same product -->\\n                                <t t-else=\\"\\" name=\\"aggregated_move_lines\\">\\n                                    <t t-set=\\"aggregated_lines\\" t-value=\\"o.move_line_ids._get_aggregated_product_quantities()\\"/>\\n                                    <t t-call=\\"stock.stock_report_delivery_aggregated_move_lines\\"/>\\n                                </t>\\n                            </t>\\n                        </tbody>\\n                    </table>\\n                    <t t-set=\\"backorders\\" t-value=\\"o.backorder_ids.filtered(lambda x: x.state not in ('done', 'cancel'))\\"/>\\n                    <t t-if=\\"o.backorder_ids and backorders\\">\\n                        <p class=\\"mt-5\\">\\n                            <span>Remaining quantities not yet delivered:</span>\\n                        </p>\\n                        <table class=\\"table table-sm\\" name=\\"stock_backorder_table\\" style=\\"table-layout: fixed;\\">\\n                            <thead>\\n                                <tr>\\n                                    <th name=\\"th_sb_product\\"><strong>Product</strong></th>\\n                                    <th/>\\n                                    <th name=\\"th_sb_quantity\\" class=\\"text-center\\"><strong>Quantity</strong></th>\\n                                </tr>\\n                            </thead>\\n                            <tbody>\\n                                <t t-foreach=\\"backorders\\" t-as=\\"backorder\\">\\n                                    <t t-set=\\"bo_lines\\" t-value=\\"backorder.move_ids.filtered(lambda x: x.product_uom_qty)\\"/>\\n                                    <tr t-foreach=\\"bo_lines\\" t-as=\\"bo_line\\">\\n                                        <td class=\\"w-auto\\">\\n                                            <span t-field=\\"bo_line.product_id\\"/>\\n                                            <p t-if=\\"bo_line.description_picking != bo_line.product_id.name and bo_line.description_picking != bo_line.product_id.display_name\\">\\n                                                <span t-field=\\"bo_line.description_picking\\"/>\\n                                            </p>\\n                                        </td>\\n                                        <td/>\\n                                        <td class=\\"text-center w-auto\\">\\n                                            <span t-field=\\"bo_line.product_uom_qty\\"/>\\n                                            <span t-field=\\"bo_line.product_uom\\"/>\\n                                        </td>\\n                                    </tr>\\n                                </t>\\n                            </tbody>\\n                        </table>\\n                    </t>\\n\\n                    <div t-if=\\"o.signature\\" class=\\"mt32 ml64 mr4\\" name=\\"signature\\">\\n                        <div class=\\"offset-8\\">\\n                            <strong>Signature</strong>\\n                        </div>\\n                        <div class=\\"offset-8\\">\\n                            <img t-att-src=\\"image_data_uri(o.signature)\\" style=\\"max-height: 4cm; max-width: 8cm;\\"/>\\n                        </div>\\n                        <div class=\\"offset-8 text-center\\">\\n                            <p t-field=\\"o.partner_id.name\\"/>\\n                        </div>\\n                    </div>\\n                </div>\\n            </t>\\n         </t>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="stock.report_delivery_document">\n        <t t-call="web.html_container">\n            <t t-call="web.external_layout">\n                <t t-set="o" t-value="o.with_context(lang=o._get_report_lang())"/>\n                <t t-set="partner" t-value="o.partner_id or (o.move_ids and o.move_ids[0].partner_id) or False"/>\n\n                <t t-set="address">\n                    <div name="div_outgoing_address">\n                        <div name="outgoing_delivery_address" t-if="o.should_print_delivery_address()">\n                            <span><strong>Delivery Address:</strong></span>\n                            <div t-field="o.move_ids[0].partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                        </div>\n                        <div name="outgoing_warehouse_address" t-elif="o.picking_type_id.code != 'internal' and o.picking_type_id.warehouse_id.partner_id">\n                            <span><strong>Warehouse Address:</strong></span>\n                            <div t-field="o.picking_type_id.warehouse_id.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                        </div>\n                    </div>\n                </t>\n                <t t-set="information_block">\n                    <div class="row">\n                        <div class="col-7" name="div_incoming_address">\n                            <t t-set="show_partner" t-value="False"/>\n                            <div name="vendor_address" t-if="o.picking_type_id.code=='incoming' and partner">\n                                <span><strong>Vendor Address:</strong></span>\n                                <t t-set="show_partner" t-value="True"/>\n                            </div>\n                            <div name="customer_address" t-if="o.picking_type_id.code=='outgoing' and partner and partner != partner.commercial_partner_id">\n                                <span><strong>Customer Address:</strong></span>\n                                <t t-set="show_partner" t-value="True"/>\n                            </div>\n                            <div t-if="show_partner" name="partner_header">\n                                <div t-field="partner.commercial_partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;, &quot;vat&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                            </div>\n                        </div>\n                    </div>\n                </t>\n                <div class="page">\n                    <h2>\n                        <span t-field="o.name"/>\n                    </h2>\n                    <div class="row mt32 mb32">\n                        <div t-if="o.origin" class="col-auto" name="div_origin">\n                            <strong>Order:</strong>\n                            <p t-field="o.origin"/>\n                        </div>\n                        <div t-if="o.state" class="col-auto" name="div_sched_date">\n                            <strong>Shipping Date:</strong>\n                            <t t-if="o.state == 'done'">\n                                <p t-field="o.date_done"/>\n                            </t>\n                            <t t-if="o.state != 'done'">\n                                <p t-field="o.scheduled_date"/>\n                           </t>\n                        </div>\n                    </div>\n                    <table class="table table-sm" t-if="o.state!='done'" name="stock_move_table">\n                        <thead>\n                            <tr>\n                                <th name="th_sm_product"><strong>Product</strong></th>\n                                <th name="th_sm_ordered"><strong>Ordered</strong></th>\n                                <th name="th_sm_quantity"><strong>Delivered</strong></th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <t t-set="lines" t-value="o.move_ids.filtered(lambda x: x.product_uom_qty)"/>\n                            <tr t-foreach="lines" t-as="move">\n                                <td>\n                                    <span t-field="move.product_id"/>\n                                    <p t-if="move.description_picking != move.product_id.name and move.description_picking != move.product_id.display_name">\n                                        <span t-field="move.description_picking"/>\n                                    </p>\n                                </td>\n                                <td>\n                                    <span t-field="move.product_uom_qty"/>\n                                    <span t-field="move.product_uom"/>\n                                </td>\n                                <td>\n                                    <span t-field="move.quantity_done"/>\n                                    <span t-field="move.product_uom"/>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                    <table class="table table-sm mt48" t-if="o.move_line_ids and o.state=='done'" name="stock_move_line_table">\n                        <t t-set="has_serial_number" t-value="False"/>\n                        <t t-set="has_serial_number" t-value="o.move_line_ids.mapped('lot_id')" groups="stock.group_lot_on_delivery_slip"/>\n                        <thead>\n                            <tr>\n                                <th name="th_sml_product"><strong>Product</strong></th>\n                                <t name="lot_serial" t-if="has_serial_number">\n                                    <th>\n                                        Lot/Serial Number\n                                    </th>\n                                </t>\n                                <th name="th_sml_qty_ordered" class="text-center" t-if="not has_serial_number">\n                                    <strong>Ordered</strong>\n                                </th>\n                                <th name="th_sml_quantity" class="text-center"><strong>Delivered</strong></th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                        <!-- This part gets complicated with different use cases (additional use cases in extensions of this report):\n                                1. If serial numbers are used and set to print on delivery slip => print lines as is, otherwise group them by overlapping\n                                    product + description + uom combinations\n                                2. If any packages are assigned => split products up by package (or non-package) and then apply use case 1 -->\n                            <!-- If has destination packages => create sections of corresponding products -->\n                            <t t-if="o.has_packages" name="has_packages">\n                                <t t-set="packages" t-value="o.move_line_ids.mapped('result_package_id')"/>\n                                <t t-foreach="packages" t-as="package">\n                                    <t t-call="stock.stock_report_delivery_package_section_line"/>\n                                    <t t-set="package_move_lines" t-value="o.move_line_ids.filtered(lambda l: l.result_package_id == package)"/>\n                                    <!-- If printing lots/serial numbers => keep products in original lines -->\n                                    <t t-if="has_serial_number">\n                                        <tr t-foreach="package_move_lines" t-as="move_line">\n                                            <t t-call="stock.stock_report_delivery_has_serial_move_line"/>\n                                        </tr>\n                                    </t>\n                                    <!-- If not printing lots/serial numbers => merge lines with same product+description+uom -->\n                                    <t t-else="">\n                                        <t t-set="aggregated_lines" t-value="package_move_lines._get_aggregated_product_quantities(strict=True)"/>\n                                        <t t-call="stock.stock_report_delivery_aggregated_move_lines"/>\n                                    </t>\n                                </t>\n                                <!-- Make sure we do another section for package-less products if they exist -->\n                                <t t-set="move_lines" t-value="o.move_line_ids.filtered(lambda l: not l.result_package_id)"/>\n                                <t t-set="aggregated_lines" t-value="o.move_line_ids._get_aggregated_product_quantities(except_package=True)"/>\n                                <t t-if="move_lines or aggregated_lines" name="no_package_move_lines">\n                                    <t t-call="stock.stock_report_delivery_no_package_section_line" name="no_package_section"/>\n                                    <t t-if="has_serial_number">\n                                        <tr t-foreach="move_lines" t-as="move_line">\n                                            <t t-call="stock.stock_report_delivery_has_serial_move_line"/>\n                                        </tr>\n                                    </t>\n                                    <t t-elif="aggregated_lines">\n                                        <t t-call="stock.stock_report_delivery_aggregated_move_lines"/>\n                                    </t>\n                                </t>\n                            </t>\n                            <!-- No destination packages -->\n                            <t t-else="">\n                                <!-- If printing lots/serial numbers => keep products in original lines -->\n                                <t t-if="has_serial_number">\n                                    <tr t-foreach="o.move_line_ids" t-as="move_line">\n                                        <t t-call="stock.stock_report_delivery_has_serial_move_line"/>\n                                    </tr>\n                                </t>\n                                <!-- If not printing lots/serial numbers => merge lines with same product -->\n                                <t t-else="" name="aggregated_move_lines">\n                                    <t t-set="aggregated_lines" t-value="o.move_line_ids._get_aggregated_product_quantities()"/>\n                                    <t t-call="stock.stock_report_delivery_aggregated_move_lines"/>\n                                </t>\n                            </t>\n                        </tbody>\n                    </table>\n                    <t t-set="backorders" t-value="o.backorder_ids.filtered(lambda x: x.state not in ('done', 'cancel'))"/>\n                    <t t-if="o.backorder_ids and backorders">\n                        <p class="mt-5">\n                            <span>Remaining quantities not yet delivered:</span>\n                        </p>\n                        <table class="table table-sm" name="stock_backorder_table" style="table-layout: fixed;">\n                            <thead>\n                                <tr>\n                                    <th name="th_sb_product"><strong>Product</strong></th>\n                                    <th/>\n                                    <th name="th_sb_quantity" class="text-center"><strong>Quantity</strong></th>\n                                </tr>\n                            </thead>\n                            <tbody>\n                                <t t-foreach="backorders" t-as="backorder">\n                                    <t t-set="bo_lines" t-value="backorder.move_ids.filtered(lambda x: x.product_uom_qty)"/>\n                                    <tr t-foreach="bo_lines" t-as="bo_line">\n                                        <td class="w-auto">\n                                            <span t-field="bo_line.product_id"/>\n                                            <p t-if="bo_line.description_picking != bo_line.product_id.name and bo_line.description_picking != bo_line.product_id.display_name">\n                                                <span t-field="bo_line.description_picking"/>\n                                            </p>\n                                        </td>\n                                        <td/>\n                                        <td class="text-center w-auto">\n                                            <span t-field="bo_line.product_uom_qty"/>\n                                            <span t-field="bo_line.product_uom"/>\n                                        </td>\n                                    </tr>\n                                </t>\n                            </tbody>\n                        </table>\n                    </t>\n\n                    <div t-if="o.signature" class="mt32 ml64 mr4" name="signature">\n                        <div class="offset-8">\n                            <strong>Signature</strong>\n                        </div>\n                        <div class="offset-8">\n                            <img t-att-src="image_data_uri(o.signature)" style="max-height: 4cm; max-width: 8cm;"/>\n                        </div>\n                        <div class="offset-8 text-center">\n                            <p t-field="o.partner_id.name"/>\n                        </div>\n                    </div>\n                </div>\n            </t>\n         </t>\n    </t>\n\n    	f	t	2023-11-01 05:02:07.049098	2023-11-01 05:02:07.049098	f
