552	16	\N	1	1	stock.immediate.transfer.view.form	stock.immediate.transfer	\N	form	stock/wizard/stock_immediate_transfer_views.xml	\N	primary	{"en_US": "<form string=\\"Immediate transfer?\\">\\n                <p>You have not recorded <i>done</i> quantities yet, by clicking on <i>apply</i> Odoo will process all the quantities.</p>\\n\\n                <!-- Added to ensure a correct default_get behavior\\n\\n                The wizard is always opened with default_pick_ids values in context,\\n                which are used to generate the backorder_confirmation_line_ids.\\n\\n                To ensure default_pick_ids is correctly converted from the context\\n                by default_get, the field has to be present in the view.\\n                -->\\n                <field name=\\"pick_ids\\" invisible=\\"1\\"/>\\n\\n                <field name=\\"show_transfers\\" invisible=\\"1\\"/>\\n                <field name=\\"immediate_transfer_line_ids\\" nolabel=\\"1\\" attrs=\\"{'invisible': [('show_transfers', '=', False)]}\\">&gt;\\n                    <tree create=\\"0\\" delete=\\"0\\" editable=\\"top\\">\\n                        <field name=\\"picking_id\\"/>\\n                        <field name=\\"to_immediate\\" widget=\\"boolean_toggle\\"/>\\n                    </tree>\\n                </field>\\n\\n                <footer>\\n                    <button name=\\"process\\" string=\\"Apply\\" type=\\"object\\" class=\\"btn-primary\\" data-hotkey=\\"q\\"/>\\n                    <button string=\\"Cancel\\" class=\\"btn-secondary\\" special=\\"cancel\\" data-hotkey=\\"z\\"/>\\n                </footer>\\n            </form>"}	<?xml version="1.0"?>\n<form string="Immediate transfer?">\n                <p>You have not recorded <i>done</i> quantities yet, by clicking on <i>apply</i> Odoo will process all the quantities.</p>\n\n                <!-- Added to ensure a correct default_get behavior\n\n                The wizard is always opened with default_pick_ids values in context,\n                which are used to generate the backorder_confirmation_line_ids.\n\n                To ensure default_pick_ids is correctly converted from the context\n                by default_get, the field has to be present in the view.\n                -->\n                <field name="pick_ids" invisible="1"/>\n\n                <field name="show_transfers" invisible="1"/>\n                <field name="immediate_transfer_line_ids" nolabel="1" attrs="{'invisible': [('show_transfers', '=', False)]}">&gt;\n                    <tree create="0" delete="0" editable="top">\n                        <field name="picking_id"/>\n                        <field name="to_immediate" widget="boolean_toggle"/>\n                    </tree>\n                </field>\n\n                <footer>\n                    <button name="process" string="Apply" type="object" class="btn-primary" data-hotkey="q"/>\n                    <button string="Cancel" class="btn-secondary" special="cancel" data-hotkey="z"/>\n                </footer>\n            </form>\n        	f	t	2023-11-01 05:02:07.049098	2023-11-01 05:02:07.049098	f
553	16	\N	1	1	stock.inventory.conflict.form.view	stock.inventory.conflict	\N	form	stock/wizard/stock_inventory_conflict.xml	\N	primary	{"en_US": "<form>\\n                <div>\\n                    <strong>Due to some stock moves done between your initial update of the quantity and now, the difference of quantity is not consistent anymore.</strong>\\n                </div>\\n                <div>\\n                    You can either :\\n                    <ul>\\n                        <li>Keep the <strong>Counted Quantity</strong> (the Difference will be updated)</li>\\n                        <li>Keep the <strong>Difference</strong> (the Counted Quantity will be updated to reflect the same difference as when you counted)</li>\\n                        <li>Discard and manually resolve the conflict</li>\\n                    </ul>\\n                </div>\\n                <div>\\n                    <br/>\\n                    <field name=\\"quant_ids\\" invisible=\\"1\\"/>\\n                    <field name=\\"quant_to_fix_ids\\" readonly=\\"1\\" style=\\"margin-top:10px;\\">\\n                        <tree editable=\\"bottom\\" create=\\"0\\" delete=\\"0\\">\\n                            <field name=\\"id\\" invisible=\\"1\\"/>\\n                            <field name=\\"tracking\\" invisible=\\"1\\"/>\\n                            <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                            <field name=\\"product_id\\" attrs=\\"{'readonly': [('id', '!=', False)]}\\" invisible=\\"context.get('single_product', False)\\" readonly=\\"context.get('single_product', False)\\" force_save=\\"1\\" options=\\"{'no_create': True}\\"/>\\n                            <field name=\\"location_id\\" attrs=\\"{'readonly': [('id', '!=', False)]}\\" invisible=\\"context.get('hide_location', False)\\" options=\\"{'no_create': True}\\"/>\\n                            <field name=\\"lot_id\\" groups=\\"stock.group_production_lot\\" attrs=\\"{                        