der>\\n                                        <field name=\\"state\\" widget=\\"statusbar\\"/>\\n                                    </header>\\n                                    <group>\\n                                        <field name=\\"product_uom_category_id\\" invisible=\\"1\\"/>\\n                                        <field name=\\"additional\\" invisible=\\"1\\"/>\\n                                        <field name=\\"move_lines_count\\" invisible=\\"1\\"/>\\n                                        <field name=\\"company_id\\" invisible=\\"1\\"/>\\n                                        <field name=\\"product_id\\" required=\\"1\\" attrs=\\"{'readonly': ['|', '&amp;', ('state', '!=', 'draft'), ('additional', '=', False), ('move_lines_count', '&gt;', 0)]}\\"/>\\n                                        <field name=\\"is_initial_demand_editable\\" invisible=\\"1\\"/>\\n                                        <field name=\\"is_quantity_done_editable\\" invisible=\\"1\\"/>\\n                                        <field name=\\"product_uom_qty\\" attrs=\\"{'invisible': [('parent.immediate_transfer', '=', True)], 'readonly': [('is_initial_demand_editable', '=', False)]}\\"/>\\n                                        <field name=\\"reserved_availability\\" string=\\"Reserved\\" attrs=\\"{'invisible': (['|','|', ('parent.state','=', 'done'), ('parent.picking_type_code', 'in', ['outgoing', 'incoming']), ('parent.immediate_transfer', '=', True)])}\\"/>\\n                                        <field name=\\"product_qty\\" invisible=\\"1\\" readonly=\\"1\\"/>\\n                                        <field name=\\"forecast_expected_date\\" invisible=\\"1\\"/>\\n                                        <field name=\\"forecast_availability\\" string=\\"Reserved\\" attrs=\\"{'invisible': ['|', ('parent.picking_type_code', '!=', 'outgoing'), ('parent.state','=', 'done')]}\\" widget=\\"forecast_widget\\"/>\\n                                        <field name=\\"quantity_done\\" string=\\"Done\\" attrs=\\"{'readonly': [('is_quantity_done_editable', '=', False)]}\\"/>\\n                                        <field name=\\"product_uom\\" attrs=\\"{'readonly': [('state', '!=', 'draft'), ('id', '!=', False)]}\\" options=\\"{'no_open': True, 'no_create': True}\\" string=\\"Unit of Measure\\" groups=\\"uom.group_uom\\"/>\\n                                        <field name=\\"description_picking\\" string=\\"Description\\"/>\\n                                    </group>\\n                                </form>\\n                            </field>\\n                            <field name=\\"id\\" invisible=\\"1\\"/>\\n                            <field name=\\"package_level_ids\\" context=\\"{'default_location_id': location_id, 'default_location_dest_id': location_dest_id, 'default_company_id': company_id}\\" attrs=\\"{'readonly': [('state', '=', 'done')], 'invisible': ['|', ('picking_type_entire_packs', '=', False), ('show_operations', '=', True)]}\\"/>\\n                            <button class=\\"oe_highlight\\" name=\\"action_put_in_pack\\" type=\\"object\\" string=\\"Put in Pack\\" attrs=\\"{'invisible': [('state', 'in', ('draft', 'done', 'cancel'))]}\\" groups=\\"stock.group_tracking_lot\\" data-hotkey=\\"shift+g\\"/>\\n                        </page>\\n                        <page string=\\"Additional Info\\" name=\\"extra\\">\\n                            <group>\\n                                <group string=\\"Other Information\\" name=\\"other_infos\\">\\n                                    <field name=\\"picking_type_code\\" invisible=\\"1\\"/>\\n                                    <field name=\\"move_type\\" attrs=\\"{'invisible': [('picking_type_code', '=', 'incoming')]}\\"/>\\n                                    <field name=\\"user_id\\" domain=\\"[('share', '=', False)]\\"/>\\n                                    <field name=\\"group_id\\" groups=\\"base.group_no_one\\"/>\\n                                    <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True}\\" force_save=\\"1\\"/>\\n                                </group>\\n                            </group>\\n                        </page>\\n                        <page string=\\"Note\\" name=\\"note\\">\\n                            <field name=\\"note\\" string=\\"Note\\" placeholder=\\"Add an internal note that will be printed on the Picking Operations sheet\\"/>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n                <div class=\\"oe_chatter\\">\\n                    <field name=\\"message_follower_ids\\"/>\\n                    <field name=\\"activity_ids\\"/>\\n                    <field name=\\"message_ids\\"/>\\n                </div>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Transfer" js_class="picking_form">\n\n                <field name="is_locked" invisible="1"/>\n                <field name="show_mark_as_todo" invisible="1"/>\n                <field name="show_check_availability" invisible="1"/>\n                <field name="show_validate" invisible="1"/>\n                <field name="show_lots_text" invisible="1"/>\n                <field name="immediate_transfer" invisible="1"/>\n                <field name="picking_type_code" invisible="1"/>\n                <field name="hide_picking_type" invisible="1"/>\n                <field name="show_operations" invisible="1" readonly="1"/>\n                <field name="show_allocation" invisible="1"/>\n                <field name="show_reserved" invisible="1" readonly="1"/>\n                <field name="move_line_exist" invisible="1"/>\n                <field name="has_packages" invisible="1"/>\n                <field name="picking_type_entire_packs" invisible="1"/>\n                <field name="use_create_lots" invisible="1"/>\n                <field name="show_set_qty_button" invisible="1"/>\n                <field name="show_clear_qty_button" invisible="1"/>\n                <field name="company_id" invisible="1"/>\n\n                <header>\n                    <button name="action_confirm" attrs="{'invisible': [('show_mark_as_todo', '=', False)]}" string="Mark as Todo" type="object" class="oe_highlight" groups="base.group_user" data-hotkey="x"/>\n                    <button name="action_assign" attrs="{'invisible': [('show_check_availability', '=', False)]}" string="Check Availability" type="object" class="oe_highlight" groups="base.group_user" data-hotkey="q"/>\n                    <button name="button_validate" attrs="{'invisible': ['|', ('state', 'in', ('waiting','confirmed')), ('show_validate', '=', False)]}" string="Validate" type="object" class="oe_highlight" groups="stock.group_stock_user" data-hotkey="v"/>\n                    <button name="button_validate" attrs="{'invisible': ['|', ('state', 'not in', ('waiting', 'confirmed')), ('show_validate', '=', False)]}" string="Validate" type="object" groups="stock.group_stock_user" class="o_btn_validate" data-hotkey="v"/>\n                    <button name="action_set_quantities_to_reservation" attrs="{'invisible': [('show_set_qty_button', '=', False)]}" string="Set quantities" type="object" groups="stock.group_stock_user" class="o_btn_validate" data-hotkey="g"/>\n                    <button name="action_clear_quantities_to_zero" attrs="{'invisible': [('show_clear_qty_button', '=', False)]}" string="Clear quantities" type="object" groups="stock.group_stock_user" class="o_btn_validate" data-hotkey="g"/>\n                    <widget name="signature" string="Sign" highlight="1" attrs="{'invisible': ['|', '|', ('id', '=', False), ('picking_type_code', '!=', 'outgoing'), ('state', '!=', 'done')]}" full_name="partner_id" groups="stock.group_stock_sign_delivery"/>\n                    <widget name="signature" string="Sign" attrs="{'invisible': ['|', '|', ('id', '=', False), ('picking_type_code', '!=', 'outgoing'), ('state', '=', 'done')]}" full_name="partner_id" groups="stock.group_stock_sign_delivery"/>\n                    <button name="do_print_picking" string="Print" groups="stock.group_stock_user" type="object" attrs="{'invisible': [('state', '!=', 'assigned')]}" data-hotkey="o"/>\n                    <button string="Print Labels" type="object" name="action_open_label_type"/>\n                    <button name="192" string="Print" attrs="{'invisible': [('state', '!=', 'done')]}" type="action" groups="base.group_user" data-hotkey="o"/>\n                    <button name="209" string="Return" attrs="{'invisible': [('state', '!=', 'done')]}" type="action" groups="base.group_user" data-hotkey="k"/>\n                    <button name="do_unreserve" string="Unreserve" groups="base.group_user" type="object" attrs="{'invisible': ['|', '|', '|', ('picking_type_code', '=', 'incoming'), ('immediate_transfer', '=', True), '&amp;', ('state', '!=', 'assigned'), ('move_type', '!=', 'one'), '&amp;', ('state', 'not in', ('assigned', 'confirmed')), ('move_type', '=', 'one')]}" data-hotkey="w"/>\n                    <button name="button_scrap" type="object" string="Scrap" attrs="{'invisible': ['|', '&amp;', ('picking_type_code', '=', 'incoming'), ('state', '!=', 'done'), '&amp;', ('picking_type_code', '=', 'outgoing'), ('state', '=', 'done')]}" data-hotkey="y"/>\n                    <button name="action_toggle_is_locked" attrs="{'invisible': ['|', ('state', 'in', ('draft','cancel')), ('is_locked', '=', False)]}" string="Unlock" groups="stock.group_stock_manager" type="object" help="If the picking is unlocked you can edit initial demand (for a draft picking) or done quantities (for a done picking)." data-hotkey="l"/>\n                    <button name="action_toggle_is_locked" attrs="{'invisible': [('is_locked', '=', True)]}" string="Lock" groups="stock.group_stock_manager" type="object" data-hotkey="l"/>\n                    <field name="state" widget="statusbar" statusbar_visible="draft,confirmed,assigned,done"/>\n                    <button name="action_cancel" attrs="{'invisible': [('state', 'not in', ('assigned', 'confirmed', 'draft', 'waiting'))]}" string="Cancel" groups="base.group_user" type="object" data-hotkey="z"/>\n                </header>\n                <sheet>\n                    <div class="oe_button_box" name="button_box">\n                        <field name="has_scrap_move" invisible="True"/>\n                        <field name="has_tracking" invisible="True"/>\n                        <button name="action_see_move_scrap" string="Scraps" type="object" class="oe_stat_button" icon="fa-arrows-v" attrs="{'invisible': [('has_scrap_move', '=', False)]}"/>\n                        <button name="action_see_packages" string="Packages" type="object" class="oe_stat_button" icon="fa-cubes" attrs="{'invisible': [('has_packages', '=', False)]}"/>\n                        <button name="188" icon="fa-arrow-up" class="oe_stat_button" string="Traceability" type="action" attrs="{'invisible': ['|', ('state', '!=', 'done'), ('has_tracking', '=', False)]}" groups="stock.group_production_lot"/>\n                        <button name="action_view_reception_report" string="Allocation" type="object" context="{'default_picking_ids': [id]}" class="oe_stat_button" icon="fa-list" attrs="{'invisible': [('show_allocation', '=', False)]}" groups="stock.group_reception_report"/>\n                        <!-- Use the following button to avoid onchange on one2many -->\n                        <button name="action_picking_move_tree" class="oe_stat_button" icon="fa-arrows-v" type="object" help="List view of operations" groups="base.group_no_one" attrs="{'invisible': ['|', '&amp;', ('show_operations', '=', True), '|', ('is_locked', '=', True), ('state', '=', 'done'), '&amp;', ('state', '=', 'done'), ('is_locked', '=', True)]}" context="{'picking_type_code': picking_type_code, 'default_picking_id': id, 'form_view_ref':'stock.view_move_form', 'address_in_id': partner_id, 'default_picking_type_id': picking_type_id, 'default_location_id': location_id, 'default_location_dest_id': location_dest_id}">\n                            <div class="o_form_field o_stat_info">\n                                <span class="o_stat_text">Operations</span>\n                            </div>\n                        </button>\n                    </div>\n                    <div class="oe_title">\n                        <h1 class="d-flex">\n                            <field name="priority" widget="priority" class="me-3" attrs="{'invisible': [('name','=','/')]}"/>\n                            <field name="name" attrs="{'invisible': [('name','=','/')]}"/>\n                        </h1>\n                    </div>\n                    <group>\n                        <group>\n                            <div class="o_td_label">\n                                <label for="partner_id" string="Delivery Address" style="font-weight:bold;" attrs="{'invisible': [('picking_type_code', '!=', 'outgoing')]}"/>\n                                <label for="partner_id" string="Receive From" style="font-weight:bold;" attrs="{'invisible': [('picking_type_code', '!=', 'incoming')]}"/>\n                                <label for="partner_id" string="Contact" style="font-weight:bold;" attrs="{'invisible': [('picking_type_code', 'in', ['incoming', 'outgoing'])]}"/>\n                            </div>\n                            <field name="partner_id" nolabel="1"/>\n                            <field name="picking_type_id" attrs="{'invisible': [('hide_picking_type', '=', True)], 'readonly': [('state', '!=', 'draft')]}"/>\n                            <field name="location_id" groups="!stock.group_stock_multi_locations" invisible="1"/>\n                            <field name="location_dest_id" groups="!stock.group_stock_multi_locations" invisible="1"/>\n                            <field name="location_id" options="{'no_create': True}" groups="stock.group_stock_multi_locations" attrs="{'invisible': [('picking_type_code', '=', 'incoming')]}"/>\n                            <field name="location_dest_id" options="{'no_create': True}" groups="stock.group_stock_multi_locations" attrs="{'invisible': [('picking_type_code', '=', 'outgoing')]}"/>\n                            <field name="backorder_id" attrs="{'invisible': [('backorder_id','=',False)]}"/>\n                        </group>\n                        <group>\n                            <label for="scheduled_date"/>\n                            <div class="o_row">\n                                <field name="scheduled_date" attrs="{'required': [('id', '!=', False)]}" decoration-warning="state not in ('done', 'cancel') and scheduled_date &lt; now" decoration-danger="state not in ('done', 'cancel') and scheduled_date &lt; current_date" decoration-bf="state not in ('done', 'cancel') and (scheduled_date &lt; current_date or scheduled_date &lt; now)"/>\n                                <field name="json_popover" nolabel="1" widget="stock_rescheduling_popover" attrs="{'invisible': [('json_popover', '=', False)]}"/>\n                            </div>\n                            <field name="date_deadline" attrs="{'invisible': ['|', ('state', 'in', ('done', 'cancel')), ('date_deadline', '=', False)]}" decoration-danger="date_deadline and date_deadline &lt; current_date" decoration-bf="date_deadline and date_deadline &lt; current_date"/>\n                            <field name="products_availability_state" invisible="1"/>\n                            <field name="products_availability" attrs="{'invisible': ['|', ('picking_type_code', '!=', 'outgoing'), ('state', 'not in', ['confirmed', 'waiting', 'assigned'])]}" decoration-success="state == 'assigned' or products_availability_state == 'available'" decoration-warning="state != 'assigned' and products_availability_state in ('expected', 'available')" decoration-danger="state != 'assigned' and products_availability_state == 'late'"/>\n                            <field name="date_done" string="Effective Date" attrs="{'invisible': [('state', '!=', 'done')]}"/>\n                            <field name="origin" placeholder="e.g. PO0032"/>\n                            <field name="owner_id" groups="stock.group_tracking_owner" attrs="{'invisible': [('picking_type_code', '!=', 'incoming')]}"/>\n                        </group>\n                    </group>\n                    <notebook>\n                        <page string="Detailed Operations" name="detailed_operations" attrs="{'invisible': [('show_operations', '=', False)]}">\n                            <field name="move_line_nosuggest_ids" attrs="{'readonly': ['|', '|', ('show_operations', '=', False), ('state', '=', 'cancel'), '&amp;', ('state', '=', 'done'), ('is_locked', '=', True)], 'invisible': [('show_reserved', '=', True)]}" context="{'tree_view_ref': 'stock.view_stock_move_line_detailed_operation_tree', 'default_picking_id': id, 'default_location_id': location_id, 'default_location_dest_id': location_dest_id, 'default_company_id': company_id}"/>\n                            <field name="move_line_ids_without_package" attrs="{'readonly': ['|', '|', ('show_operations', '=', False), ('state', '=', 'cancel'), '&amp;', ('state', '=', 'done'), ('is_locked', '=', True)], 'invisible': [('show_reserved', '=', False)]}" context="{'tree_view_ref': 'stock.view_stock_move_line_detailed_operation_tree', 'default_picking_id': id, 'default_location_id': location_id, 'default_location_dest_id': location_dest_id, 'default_company_id': company_id}"/>\n                            <field name="package_level_ids_details" context="{'default_location_id': location_id, 'default_location_dest_id': location_dest_id, 'default_company_id': company_id}" attrs="{'readonly': [('state', '=', 'done')], 'invisible': ['|', ('picking_type_entire_packs', '=', False), ('show_operations', '=', False)]}"/>\n                            <button class="oe_highlight" name="action_put_in_pack" type="object" string="Put in Pack" attrs="{'invisible': [('state', 'in', ('draft', 'done', 'cancel'))]}" groups="stock.group_tracking_lot" data-hotkey="shift+g"/>\n                        </page>\n\n                        <page string="Operations" name="operations">\n                            <field name="move_ids_without_package" mode="tree,kanban" widget="stock_move_one2many" attrs="{'readonly': ['&amp;', ('state', '=', 'done'), ('is_locked', '=', True)]}" context="{'default_company_id': company_id, 'default_date': scheduled_date, 'default_date_deadline': date_deadline, 'picking_type_code': picking_type_code, 'default_picking_id': id, 'form_view_ref':'stock.view_move_form', 'address_in_id': partner_id, 'default_picking_type_id': picking_type_id, 'default_location_id': location_id, 'default_location_dest_id': location_dest_id, 'default_partner_id': partner_id}" add-label="Add a Product">\n                                <tree decoration-danger="not parent.immediate_transfer and state != 'done' and quantity_done &gt; reserved_availability and show_reserved_availability" decoration-muted="scrapped == True or state == 'cancel' or (state == 'done' and is_locked == True)" string="Stock Moves" editable="bottom">\n                                    <field name="company_id" invisible="1"/>\n                                    <field name="name" invisible="1"/>\n                                    <field name="state" invisible="1" readonly="0"/>\n                                    <field name="picking_type_id" invisible="1"/>\n                                    <field name="location_id" invisible="1"/>\n                                    <field name="location_dest_id" invisible="1"/>\n                                    <field name="partner_id" invisible="1"/>\n                                    <field name="scrapped" invisible="1"/>\n                                    <field name="picking_code" invisible="1"/>\n                                    <field name="product_type" invisible="1"/>\n                                    <field name="show_details_visible" invisible="1"/>\n                                    <field name="show_reserved_availability" invisible="1"/>\n                                    <field name="show_operations" invisible="1" readonly="1"/>\n                                    <field name="additional" invisible="1"/>\n                                    <field name="move_lines_count" invisible="1"/>\n                                    <field name="is_locked" invisible="1"/>\n                                    <field name="product_uom_category_id" invisible="1"/>\n                                    <field name="has_tracking" invisible="1"/>\n                                    <field name="display_assign_serial" invisible="1"/>\n                                    <field name="product_id" required="1" context="{'default_detailed_type': 'product'}" attrs="{'readonly': ['|', '&amp;', ('state', '!=', 'draft'), ('additional', '=', False), ('move_lines_count', '&gt;', 0)]}"/>\n                                    <field name="description_picking" string="Description" optional="hide"/>\n                                    <field name="date" optional="hide"/>\n                                    <field name="date_deadline" optional="hide"/>\n                                    <field name="is_initial_demand_editable" invisible="1"/>\n                                    <field name="is_quantity_done_editable" invisible="1"/>\n                                    <field name="product_packaging_id" groups="product.group_stock_packaging"/>\n                                    <field name="product_uom_qty" string="Demand" attrs="{'column_invisible': [('parent.immediate_transfer', '=', True)], 'readonly': ['|', ('is_initial_demand_editable', '=', False), '&amp;', '&amp;', ('show_operations', '=', True), ('is_locked', '=', True), ('is_initial_demand_editable', '=', False)]}"/>\n                                    <button type="object" name="action_product_forecast_report" title="Forecast Report" icon="fa-area-chart" attrs="{'invisible': ['|', '&amp;', ('reserved_availability', '=', 0), ('forecast_availability', '&lt;=', 0), '|', ('parent.immediate_transfer', '=', True), '&amp;', ('parent.picking_type_code', '=', 'outgoing'), ('state', '!=', 'draft')]}"/>\n                                    <button type="object" name="action_product_forecast_report" title="Forecast Report" icon="fa-area-chart text-danger" attrs="{'invisible': ['|', '|', ('reserved_availability', '!=', 0), ('forecast_availability', '&gt;', 0), '|', ('parent.immediate_transfer', '=', True), '&amp;', ('parent.picking_type_code', '=', 'outgoing'), ('state', '!=', 'draft')]}"/>\n                                    <field name="forecast_expected_date" invisible="1"/>\n                                    <field name="forecast_availability" string="Reserved" attrs="{'column_invisible': ['|', '|', ('parent.state', 'in', ['draft', 'done']), ('parent.picking_type_code', '!=', 'outgoing'), ('parent.immediate_transfer', '=', True)]}" widget="forecast_widget"/>\n                                    <field name="reserved_availability" string="Reserved" attrs="{'column_invisible': ['|', '|', ('parent.state', 'in', ['draft', 'done']), ('parent.picking_type_code', 'in', ['incoming', 'outgoing']), ('parent.immediate_transfer', '=', True)]}"/>\n                                    <field name="product_qty" invisible="1" readonly="1"/>\n                                    <field name="quantity_done" string="Done" attrs="{'readonly': [('product_id', '=', False)], 'column_invisible':[('parent.state', '=', 'draft'), ('parent.immediate_transfer', '=', False)]}"/>\n                                    <field name="product_uom" attrs="{'readonly': [('state', '!=', 'draft'), ('additional', '=', False)]}" options="{'no_open': True, 'no_create': True}" string="Unit of Measure" groups="uom.group_uom"/>\n                                    <field name="lot_i