886	16	\N	1	1	mass_mailing_mail_style	\N	mass_mailing.mass_mailing_mail_style	qweb	mass_mailing/data/mailing_data_templates.xml	\N	primary	{"en_US": "<t t-name=\\"mass_mailing.mass_mailing_mail_style\\">\\n        <style>\\n            .o_layout * {\\n                box-sizing: border-box !important;\\n            }\\n            .o_layout :not(.fa) {\\n                font-family: Arial,Helvetica Neue,Helvetica,sans-serif;\\n            }\\n            /* Remove space around the email design. */\\n                html,\\n                body {\\n                    margin: 0 auto !important;\\n                    padding: 0 !important;\\n                    height: 100% !important;\\n                    width: 100% !important;\\n                }\\n\\n                /* Stop Outlook resizing small text. */\\n                * {\\n                    -ms-text-size-adjust: 100%;\\n                }\\n\\n                /* Stop Outlook from adding extra spacing to tables. */\\n                table,\\n                td {\\n                    mso-table-lspace: 0pt !important;\\n                    mso-table-rspace: 0pt !important;\\n                }\\n\\n                /* Use a better rendering method when resizing images in Outlook IE. */\\n                img {\\n                    -ms-interpolation-mode:bicubic;\\n                }\\n\\n                /* Prevent Windows 10 Mail from underlining links. Styles for underlined links should be inline. */\\n                a {\\n                    text-decoration: none;\\n                }\\n            @media screen and (max-width: 768px) {\\n                .o_mail_snippet_general .container {\\n                    width: 100% !important;\\n                }\\n                .s_header_social table td, .s_header_text_social table td, .s_header_logo table td,\\n                .o_mail_block_footer_social td,\\n                .s_showcase td,\\n                .s_mail_product_list td,\\n                .s_references td {\\n                    text-align: center !important;\\n                }\\n            }\\n            @media screen and (max-width: 1135px) {\\n                .o_stacking_wrapper {\\n                    width: 100% !important;\\n                    height: unset !important;\\n                }\\n                td {\\n                    max-width: inherit !important;\\n                }\\n                img:only-child:not(.img-fluid) {\\n                    object-fit: cover;\\n                    min-width: 100% !important;\\n                }\\n                .o_desktop_h100 {\\n                    height: unset !important;\\n                }\\n            }\\n        </style>\\n    </t>"}	<?xml version="1.0"?>\n<t t-name="mass_mailing.mass_mailing_mail_style">\n        <style>\n            .o_layout * {\n                box-sizing: border-box !important;\n            }\n            .o_layout :not(.fa) {\n                font-family: Arial,Helvetica Neue,Helvetica,sans-serif;\n            }\n            /* Remove space around the email design. */\n                html,\n                body {\n                    margin: 0 auto !important;\n                    padding: 0 !important;\n                    height: 100% !important;\n                    width: 100% !important;\n                }\n\n                /* Stop Outlook resizing small text. */\n                * {\n                    -ms-text-size-adjust: 100%;\n                }\n\n                /* Stop Outlook from adding extra spacing to tables. */\n                table,\n                td {\n                    mso-table-lspace: 0pt !important;\n                    mso-table-rspace: 0pt !important;\n                }\n\n                /* Use a better rendering method when resizing images in Outlook IE. */\n                img {\n                    -ms-interpolation-mode:bicubic;\n                }\n\n                /* Prevent Windows 10 Mail from underlining links. Styles for underlined links should be inline. */\n                a {\n                    text-decoration: none;\n                }\n            @media screen and (max-width: 768px) {\n                .o_mail_snippet_general .container {\n                    width: 100% !important;\n                }\n                .s_header_social table td, .s_header_text_social table td, .s_header_logo table td,\n                .o_mail_block_footer_social td,\n                .s_showcase td,\n                .s_mail_product_list td,\n                .s_references td {\n                    text-align: center !important;\n                }\n            }\n            @media screen and (max-width: 1135px) {\n                .o_stacking_wrapper {\n                    width: 100% !important;\n                    height: unset !important;\n                }\n                td {\n                    max-width: inherit !important;\n                }\n                img:only-child:not(.img-fluid) {\n                    object-fit: cover;\n                    min-width: 100% !important;\n                }\n                .o_desktop_h100 {\n                    height: unset !important;\n                }\n            }\n        </style>\n    </t>\n	f	t	2023-11-01 05:02:17.702206	2023-11-01 05:02:17.702206	f
887	16	\N	1	1	Mass Mailing: A/B Test Description	\N	mass_mailing.ab_testing_description	qweb	mass_mailing/data/mailing_data_templates.xml	\N	primary	{"en_US": "<t name=\\"Mass Mailing: A/B Test Description\\" t-name=\\"mass_mailing.ab_testing_description\\">\\n        <div name=\\"ab_testing_description\\" class=\\"mb-2\\">\\n            <t t-if=\\"mailing.ab_testing_completed\\">\\n                <p t-if=\\"mailing.ab_testing_pc == 100\\">\\n                    This <t t-out=\\"mailing.mailing_type_description\\"/> is the winner of the A/B testing campaign and has been sent to all remaining recipients.\\n                </p>\\n                <p t-else=\\"\\">The winner has already been sent. Use <b>Compare Version</b> to get an overview of this A/B testing campaign.</p>\\n            </t>\\n            <t t-elif=\\"mailing.ab_testing_mailings_count &gt;= 2\\">\\n                <p>\\n                    A sample of <b><t t-out=\\"mailing.ab_testing_pc\\"/>% of recipients</b> will receive this <b><t t-out=\\"mailing.mailing_type_description\\"/></b>, and <t t-out=\\"other_ab_testing_pc\\"/>% receive one of the\\n                    <b><t t-out=\\"mailing.ab_testing_mailings_count - 1\\"/> other versions</b> from the same campaign.\\n                </p>\\n                <p>\\n\\t\\t    <t t-if=\\"mailing.ab_testing_winner_selection == 'manual'\\">Don't forget to send your preferred version</t>\\n\\t\\t    <t t-elif=\\"not mailing.ab_testing_schedule_datetime\\">Since the date and time for this test has not been scheduled, don't forget to manually send your preferred version.</t>\\n                    <t t-else=\\"\\">\\n                        Then on <b><t t-out=\\"mailing.ab_testing_schedule_datetime.strftime('%b %d, %Y')\\"/></b> the <t t-out=\\"mailing.mailing_type_description\\"/> having the <b><t t-out=\\"ab_testing_winner_selection_description\\"/></b> will be sent\\n                    </t> to the remaining <t t-out=\\"remaining_ab_testing_pc\\"/>% of recipients.\\n                </p>\\n            </t>\\n            <t t-else=\\"\\">\\n                <p>\\n                    A sample of <b><t t-out=\\"mailing.ab_testing_pc\\"/>% of recipients</b> will receive this <b><t t-out=\\"mailing.mailing_type_description\\"/></b>.\\n                </p>\\n                <p>Try different variations in the campaign to compare their <t t-out=\\"ab_testing_winner_selection_description\\"/>.</p>\\n                <p>\\n                    <t t-if=\\"mailing.ab_testing_winner_selection != 'manual'\\">Once the best version is identified, we will send the best one to the remaining recipients.</t>\\n                    <t t-else=\\"\\">\\n                        The actual <t t-out=\\"mailing.mailing_type_description\\"/> will be sent to the remaining recipients.\\n                    </t>\\n                </p>\\n            </t>\\n        </div>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Mass Mailing: A/B Test Description" t-name="mass_mailing.ab_testing_description">\n        <div name="ab_testing_description" class="mb-2">\n            <t t-if="mailing.ab_testing_completed">\n                <p t-if="mailing.ab_testing_pc == 100">\n                    This <t t-out="mailing.mailing_type_description"/> is the winner of the A/B testing campaign and has been sent to all remaining recipients.\n                </p>\n                <p t-else="">The winner has already been sent. Use <b>Compare Version</b> to get an overview of this A/B testing campaign.</p>\n            </t>\n            <t t-elif="mailing.ab_testing_mailings_count &gt;= 2">\n                <p>\n                    A sample of <b><t t-out="mailing.ab_testing_pc"/>% of recipients</b> will receive this <b><t t-out="mailing.mailing_type_description"/></b>, and <t t-out="other_ab_testing_pc"/>% receive one of the\n                    <b><t t-out="mailing.ab_testing_mailings_count - 1"/> other versions</b> from the same campaign.\n                </p>\n                <p>\n\t\t    <t t-if="mailing.ab_testing_winner_selection == 'manual'">Don't forget to send your preferred version</t>\n\t\t    <t t-elif="not mailing.ab_testing_schedule_datetime">Since the date and time for this test has not been scheduled, don't forget to manually send your preferred version.</t>\n                    <t t-else="">\n                        Then on <b><t t-out="mailing.ab_testing_schedule_datetime.strftime('%b %d, %Y')"/></b> the <t t-out="mailing.mailing_type_description"/> having the <b><t t-out="ab_testing_winner_selection_description"/></b> will be sent\n                    </t> to the remaining <t t-out="remaining_ab_testing_pc"/>% of recipients.\n                </p>\n            </t>\n            <t t-else="">\n                <p>\n                    A sample of <b><t t-out="mailing.ab_testing_pc"/>% of recipients</b> will receive this <b><t t-out="mailing.mailing_type_description"/></b>.\n                </p>\n                <p>Try different variations in the campaign to compare their <t t-out="ab_testing_winner_selection_description"/>.</p>\n                <p>\n                    <t t-if="mailing.ab_testing_winner_selection != 'manual'">Once the best version is identified, we will send the best one to the remaining recipients.</t>\n                    <t t-else="">\n                        The actual <t t-out="mailing.mailing_type_description"/> will be sent to the remaining recipients.\n                    </t>\n                </p>\n            </t>\n        </div>\n    </t>\n\n    	f	t	2023-11-01 05:02:17.702206	2023-11-01 05:02:17.702206	f
