\" options=\\"{'dynamic_placeholder': true}\\" attrs=\\"{'readonly': [('state', 'in', ('sending', 'done'))]}\\" widget=\\"char_emojis\\" placeholder=\\"e.g. New Sale on all T-shirts\\"/>\\n                                <field name=\\"favorite\\" invisible=\\"1\\"/>\\n                                <button type=\\"object\\" name=\\"action_set_favorite\\" class=\\"o_mass_mailing_favorite p-0\\" icon=\\"fa-star-o\\" attrs=\\"{'invisible': [('favorite', '=', True)]}\\" title=\\"Add to Templates\\"/>\\n                                <button type=\\"object\\" name=\\"action_remove_favorite\\" class=\\"o_mass_mailing_favorite p-0\\" icon=\\"fa-star\\" attrs=\\"{'invisible': [('favorite', '=', False)]}\\" title=\\"Remove from Templates\\"/>\\n                            </div>\\n                            <label for=\\"mailing_model_id\\" string=\\"Recipients\\"/>\\n                            <div name=\\"mailing_model_id_container\\">\\n                                <div class=\\"d-flex align-items-baseline flex-wrap\\">\\n                                    <div class=\\"me-5\\">\\n                                        <field name=\\"mailing_model_id\\" options=\\"{'no_open': True, 'no_create': True}\\" attrs=\\"{'readonly': [('state', 'in', ('sending', 'done'))]}\\"/>\\n                                    </div>\\n                                    <div attrs=\\"{'invisible': [('mailing_model_name', '!=', 'mailing.list')]}\\" class=\\"o_mass_mailing_contact_list_ids pt-1 pt-sm-0\\">\\n                                        <label for=\\"contact_list_ids\\" string=\\"Select mailing lists:\\" class=\\"oe_edit_only pe-2\\"/>\\n                                        <div class=\\"d-inline-flex flex-row align-items-center\\">\\n                                            <field name=\\"contact_list_ids\\" widget=\\"many2many_tags\\" placeholder=\\"Select mailing lists...\\" class=\\"oe_inline mb-0\\" context=\\"{'form_view_ref': 'mass_mailing.mailing_list_view_form_simplified'}\\" attrs=\\"{                                                     'required':[('mailing_model_name','=','mailing.list')],                                                     'readonly': [('state', 'in', ('sending', 'done'))]                                             }\\"/>\\n                                            <button icon=\\"fa-user-plus\\" type=\\"object\\" class=\\"btn btn-secondary py-0 px-1 ms-1\\" attrs=\\"{'invisible': ['|', '|', ('contact_list_ids', '=', False), ('contact_list_ids', '=', []), ('state', 'in', ('sending', 'done'))]}\\" name=\\"action_view_mailing_contacts\\" title=\\"Add Mailing Contacts\\"/>\\n                                        </div>\\n                                    </div>\\n                                    <div attrs=\\"{'invisible': [('mailing_model_name', '=', 'mailing.list')]}\\" class=\\"o_td_label\\">\\n                                        <!-- We don't want to display label in edit mode, unless mailing is in sending or done state (where filter will be readonly) -->\\n                                        <label for=\\"mailing_filter_id\\" string=\\"Filter\\" class=\\"oe_read_only me-4\\" attrs=\\"{'invisible': ['|', ('state', 'in', ('sending', 'done')), ('mailing_filter_id', '=', False)]}\\"/>\\n                                        <label for=\\"mailing_filter_id\\" string=\\"Filter\\" class=\\"me-4\\" attrs=\\"{'invisible': ['|', ('state', 'not in', ('sending', 'done')), ('mailing_filter_id', '=', False)]}\\"/>\\n                                        <field name=\\"mailing_filter_id\\" placeholder=\\"Reload a favorite filter\\" class=\\"w-auto\\" widget=\\"mailing_filter\\" options=\\"{'no_create': 1, 'no_open': 1, 'domain_field': 'mailing_domain', 'model_field': 'mailing_model_id'}\\" attrs=\\"{'readonly': [('state', 'in', ('sending', 'done'))]}\\"/>\\n                                    </div>\\n                                    <field name=\\"mailing_filter_count\\" invisible=\\"1\\"/>\\n                                    <field name=\\"mailing_filter_domain\\" invisible=\\"1\\"/>\\n                                </div>\\n\\n                                <field name=\\"mailing_model_name\\" invisible=\\"1\\"/>\\n                                <field name=\\"mailing_model_real\\" invisible=\\"1\\"/>\\n                                <div class=\\"w-lg-50\\" attrs=\\"{'invisible': [('mailing_model_name', '=', 'mailing.list')]}\\">\\n                                    <field name=\\"mailing_domain\\" widget=\\"domain\\" options=\\"{'model': 'mailing_model_real'}\\" attrs=\\"{'readonly': [('state', 'in', ('sending', 'done'))]}\\"/>\\n                                </div>\\n                            </div>\\n                        </group>\\n                        <notebook>\\n                            <page string=\\"Mail Body\\" name=\\"mail_body\\">\\n                                <div class=\\"position-relative\\">\\n                                    <div class=\\"mt-n2\\">\\n                                        <field name=\\"body_arch\\" class=\\"o_mail_body\\" widget=\\"mass_mailing_html\\" options=\\"{                                                 'snippets': 'mass_mailing.email_designer_snippets',                                                 'cssEdit': 'mass_mailing.iframe_css_assets_edit',                                                 'inline-field': 'body_html',                                                 'dynamic_placeholder': true,                                                 'cssReadonly': 'mass_mailing.iframe_css_assets_edit'                                         }\\" attrs=\\"{'readonly': [('state', 'in', ('sending', 'done'))]}\\"/>\\n                                    </div>\\n                                    <field name=\\"is_body_empty\\" invisible=\\"1\\"/>\\n                                    <div class=\\"o_view_nocontent oe_read_only\\" attrs=\\"{'invisible': ['|', ('is_body_empty', '=', False), ('state', 'in', ('sending', 'done'))]}\\">\\n                                        <div class=\\"o_nocontent_help\\">\\n                                            <p class=\\"o_view_nocontent_smiling_face\\">\\n                                                This mailing has no selected design (yet!).\\n                                            </p>\\n                                        </div>\\n                                    </div>\\n                                </div>\\n                            </page>\\n                            <page string=\\"A/B Tests\\" name=\\"ab_testing\\">\\n                                <group>\\n                                    <group>\\n                                        <label for=\\"ab_testing_enabled\\"/>\\n                                        <span class=\\"d-flex\\">\\n                                            <field name=\\"ab_testing_enabled\\" attrs=\\"{'readonly': [('state', '!=', 'draft')]}\\" force_save=\\"1\\"/>\\n                                            <span class=\\"d-flex\\" attrs=\\"{'invisible': [('ab_testing_enabled', '=', False)]}\\">\\n                                                on <field name=\\"ab_testing_pc\\" class=\\"mx-1 text-center\\" attrs=\\"{'readonly': [('state', '!=', 'draft')]}\\"/> %\\n                                            </span>\\n                                        </span>\\n                                        <field name=\\"ab_testing_winner_selection\\" attrs=\\"{'required': [('ab_testing_enabled', '=', True), ('mailing_type', '=', 'mail')], 'invisible': ['|', ('ab_testing_enabled', '=', False), ('mailing_type', '!=', 'mail')], 'readonly': [('state', '!=', 'draft')]}\\"/>\\n                                        <field name=\\"ab_testing_schedule_datetime\\" attrs=\\"{'required': [('ab_testing_enabled', '=', True), ('ab_testing_winner_selection', '!=', 'manual')], 'readonly': ['|', ('ab_testing_enabled', '=', False), ('state', '!=', 'draft')], 'invisible': ['|', ('ab_testing_enabled', '=', False), ('ab_testing_winner_selection', '=', 'manual')]}\\"/>\\n                                    </group>\\n                                    <div>\\n                                        <field name=\\"ab_testing_mailings_count\\" invisible=\\"1\\"/>\\n                                        <field name=\\"ab_testing_completed\\" invisible=\\"1\\"/>\\n                                        <field name=\\"ab_testing_description\\" nolabel=\\"1\\"/>\\n                                        <div attrs=\\"{'invisible': ['|', ('ab_testing_mailings_count', '&lt;', 2), ('ab_testing_enabled', '=', False)]}\\">\\n                                            <button name=\\"action_compare_versions\\" type=\\"object\\" class=\\"btn btn-link d-block\\">\\n                                                <i class=\\"fa fa-bar-chart\\"/> Compare Version\\n                                            </button>\\n                                            <button name=\\"action_duplicate\\" type=\\"object\\" class=\\"btn btn-link d-block\\" attrs=\\"{'invisible': [('ab_testing_completed', '=', True)]}\\">\\n                                                <i class=\\"fa fa-copy\\"/> Create an Alternative\\n                                            </button>\\n                                            <button name=\\"action_send_winner_mailing\\" type=\\"object\\" class=\\"btn btn-link d-block\\" attrs=\\"{'invisible': [('ab_testing_completed', '=', True)]}\\">\\n                                                <i class=\\"fa fa-envelope\\"/> <span name=\\"ab_test_manual\\" attrs=\\"{'invisible': [('ab_testing_winner_selection', '!=', 'manual')]}\\">\\n                                                    Send this version to remaining recipients\\n                                                </span> <span name=\\"ab_test_auto\\" attrs=\\"{'invisible': [('ab_testing_winner_selection', '=', 'manual')]}\\">\\n                                                    Send Winner Now\\n                                                </span>\\n                                            </button>\\n                                            <button name=\\"action_select_as_winner\\" type=\\"object\\" class=\\"btn btn-link d-block\\" attrs=\\"{'invisible': ['|', ('ab_testing_completed', '!=', False), ('ab_testing_winner_selection', '!=', 'manual')]}\\">\\n                                                <i class=\\"fa fa-envelope\\"/> Send this as winner\\n                                            </button>\\n                                        </div>\\n                                        <button name=\\"action_duplicate\\" type=\\"object\\" class=\\"btn btn-primary\\" attrs=\\"{'invisible': ['|', ('ab_testing_mailings_count', '&gt;=', 2), ('ab_testing_enabled', '=', False)]}\\">\\n                                            Create an Alternative Version\\n                                        </button>\\n                                    </div>\\n                                </group>\\n                            </page>\\n                            <page string=\\"Settings\\" name=\\"settings\\">\\n                                <group>\\n                                    <group string=\\"Email Content\\" name=\\"email_content\\" attrs=\\"{'invisible': [('mailing_type', '!=', 'mail')]}\\">\\n                                        <field class=\\"o_text_overflow\\" name=\\"preview\\" string=\\"Preview Text\\" options=\\"{'dynamic_placeholder': true}\\" attrs=\\"{'readonly': [('state', 'in', ('sending', 'done'))]}\\" widget=\\"char_emojis\\" placeholder=\\"e.g. Check it out before it's too late!\\"/>\\n                                        <field name=\\"email_from\\" attrs=\\"{'readonly': [('state', 'in', ('sending', 'done'))]}\\"/>\\n                                        <label for=\\"reply_to\\"/>\\n                                        <div name=\\"reply_to_details\\">\\n                                            <field name=\\"reply_to_mode\\" widget=\\"radio\\" attrs=\\"{                                                     'invisible': [('mailing_model_name', 'in', ['mailing.contact', 'res.partner', 'mailing.list'])],                                                     'readonly': [('state', 'in', ('sending', 'done'))]                                             }\\"/>\\n                                            <field name=\\"reply_to\\" attrs=\\"{                                                     'required': [('reply_to_mode', '=', 'new')],                                                     'invisible': [('reply_to_mode', '=', 'update')],                                                     'readonly': [('state', 'in', ('sending', 'done'))]                                             }\\"/>\\n                                            <div style=\\"margin-top:-5px\\">\\n                                                <small class=\\"oe_edit_only text-muted mb-2\\" style=\\"font-size:74%\\" attrs=\\"{'invisible': ['|', ('reply_to_mode', '=', 'update'), ('mailing_model_name', 'in', ['mailing.contact', 'res.partner', 'mailing.list'])],}\\">\\n                                                    To track replies, this address must belong to this database.\\n                                                </small>\\n                                            </div>\\n                                        </div>\\n                                        <label for=\\"attachment_ids\\"/>\\n                                        <div name=\\"attachment_ids_details\\">\\n                                            <field name=\\"attachment_ids\\" widget=\\"many2many_binary\\" string=\\"Attach a file\\" class=\\"oe_inline\\" attrs=\\"{'readonly': [('state', 'in', ('sending', 'done'))]}\\"/>\\n                                        </div>\\n                                    </group>\\n                                    <group string=\\"Tracking\\">\\n                                        <field name=\\"campaign_id\\" string=\\"Campaign\\" groups=\\"mass_mailing.group_mass_mailing_campaign\\" options=\\"{'create_name_field': 'title', 'always_reload': True}\\" attrs=\\"{'readonly': [('state', 'in', ('sending', 'done'))]}\\"/>\\n                                        <field name=\\"medium_id\\" string=\\"Medium\\" required=\\"True\\" groups=\\"base.group_no_one\\" attrs=\\"{'readonly': [('state', 'in', ('sending', 'done'))]}\\"/>\\n                                        <field name=\\"source_id\\" string=\\"Source\\" readonly=\\"1\\" required=\\"False\\" class=\\"o_text_overflow\\" groups=\\"base.group_no_one\\" attrs=\\"{'readonly': [('state', 'in', ('sending', 'done'))]}\\"/>\\n                                        <field name=\\"user_id\\" widget=\\"many2one_avatar_user\\" domain=\\"[('share', '=', False)]\\"/>\\n                                    </group>\\n                                    <group string=\\"Advanced\\" groups=\\"base.group_no_one\\">\\n                                        <field name=\\"mail_server_available\\" invisible=\\"1\\"/>\\n                                        <field name=\\"name\\" required=\\"False\\" string=\\"Name\\" attrs=\\"{'readonly': [('state', 'in', ('sending', 'done'))]}\\"/>\\n                                        <field name=\\"mail_server_id\\" attrs=\\"{'readonly': [('state', 'in', ('sending', 'done'))],                                          'invisible': [('mail_server_available', '=', False)]}\\"/>\\n                                        <field name=\\"keep_archives\\" attrs=\\"{'readonly': [('state', 'in', ('sending', 'done'))]}\\"/>\\n                                    </group>\\n                                </group>\\n                            </page>\\n                        </notebook>\\n                    </sheet>\\n                    <div class=\\"oe_chatter\\">\\n                        <field name=\\"message_follower_ids\\" groups=\\"base.group_user\\"/>\\n                        <field name=\\"message_ids\\"/>\\n                        <field name=\\"activity_ids\\"/>\\n                    </div>\\n                </form>"}	<?xml version="1.0"?>\n<form string="Mailing" class="o_mass_mailing_mailing_form">\n                    <header style="min-height:31px;">\n                        <button name="action_launch" type="object" class="oe_highlight" string="Send" attrs="{'invisible': [('state', 'in', ('in_queue',  'sending', 'done'))]}" data-hotkey="v" confirm="This will send the email to all recipients. Do you still want to proceed ?"/>\n                        <button name="action_schedule" type="object" class="btn-secondary" string="Schedule" attrs="{'invisible': [('state', 'in', ('in_queue',  'sending', 'done'))]}" data-hotkey="x"/>\n                        <button name="action_duplicate" type="object" class="btn-secondary" string="Duplicate" data-hotkey="d" attrs="{'invisible': [('state', '!=', 'done')]}"/>\n                        <button name="action_test" type="object" class="btn-secondary" string="Test" data-hotkey="k"/>\n                        <button name="action_cancel" type="object" attrs="{'invisible': [('state', '!=', 'in_queue')]}" class="btn-secondary" string="Cancel" data-hotkey="z"/>\n                        <button name="action_retry_failed" type="object" attrs="{'invisible': ['|', ('state', '!=', 'done'), ('failed', '=', 0)]}" class="oe_highlight" string="Retry" data-hotkey="y"/>\n\n                        <field name="state" readonly="1" widget="statusbar"/>\n                    </header>\n                    <div class="alert alert-info text-center" role="alert" attrs="{'invisible': ['&amp;','&amp;','&amp;','&amp;','&amp;',('state', '!=', 'in_queue'),('sent', '=', 0),('canceled', '=', 0),('scheduled', '=', 0),('failed', '=', 0),('warning_message', '=', False)]}">\n                        <div class="o_mails_canceled" attrs="{'invisible': [('canceled', '=', 0)]}">\n                            <button class="btn-link py-0" name="action_view_traces_canceled" type="object">\n                                <strong>\n                                    <field name="canceled" class="oe_inline me-2"/>\n                                    <span name="canceled_text">emails have been canceled and will not be sent.</span>\n                                </strong>\n                            </button>\n                        </div>\n                        <div class="o_mails_scheduled" attrs="{'invisible': [('scheduled', '=', 0)]}">\n                            <button class="btn-link py-0" name="action_view_traces_scheduled" type="object">\n                                <strong>\n                                    <field name="scheduled" class="oe_inline me-2"/>\n                                    <span name="scheduled_text">emails are in queue and will be sent soon.</span>\n                                </strong>\n                            </button>\n                        </div>\n                        <div class="o_mails_sent" attrs="{'invisible': ['&amp;', ('sent', '=', 0), ('state', 'in', ('draft', 'test', 'in_queue'))]}">\n                            <button class="btn-link py-0" name="action_view_traces_sent" type="object">\n                                <strong>\n                                    <field name="sent" class="oe_inline me-2"/>\n                                    <span name="sent">emails have been sent.</span>\n                                </strong>\n                            </button>\n                        </div>\n                        <div class="o_mails_failed" attrs="{'invisible': ['|', ('state', '!=', 'done'), ('failed', '=', 0)]}">\n                            <button class="btn-link py-0" name="action_view_traces_failed" type="object">\n                                <strong>\n                                    <field name="failed" class="oe_inline me-2"/>\n                                    <span name="failed_text">emails could not be sent.</span>\n                                </strong>\n                            </button>\n                        </div>\n                        <div class="o_mails_in_queue" attrs="{'invisible': [('state', '!=', 'in_queue')]}">\n                            <strong>\n                                <span name="next_departure_text">This mailing is scheduled for </span>\n                                <field name="next_departure" class="oe_inline"/>.\n                            </strong>\n                        </div>\n                        <div attrs="{'invisible': [('warning_message', '=', False)]}">\n                            <strong><field name="warning_message"/></strong>\n                        </div>\n                    </div>\n\n                    <sheet>\n                        <div class="oe_button_box" name="button_box">\n                            <button name="action_view_delivered" id="button_view_delivered" type="object" context="{'search_default_filter_delivered': True}" attrs="{'invisible': [('state', 'in', ('draft','test'))]}" class="oe_stat_button">\n                                <field name="received_ratio" string="Received" widget="percentpie"/>\n                            </button>\n                            <button name="action_view_opened" type="object" context="{'search_default_filter_opened': True}" attrs="{'invisible': [('state', 'in', ('draft','test'))]}" class="oe_stat_button">\n                                <field name="opened_ratio" string="Opened" widget="percentpie"/>\n                            </button>\n                            <button name="action_view_clicked" type="object" context="{'search_default_filter_clicked': True}" attrs="{'invisible': [('state', 'in', ('draft','test'))]}" class="oe_stat_button">\n                                <field name="clicks_ratio" string="Clicked" widget="percentpie"/>\n                            </button>\n                            <button name="action_view_replied" type="object" context="{'search_default_filter_replied': True}" attrs="{'invisible': [('state', 'in', ('draft','test'))]}" class="oe_stat_button">\n                                <field name="replied_ratio" string="Replied" widget="percentpie"/>\n                            </button>\n                            <button name="action_view_bounced" type="object" context="{'search_default_filter_bounced': True}" attrs="{'invisible': [('state', 'in', ('draft','test'))]}" class="oe_stat_button">\n                                <field name="bounced_ratio" string="Bounced" widget="percentpie"/>\n                            </button>\n                        </div>\n                        <widget name="web_ribbon" title="Archived" bg_color="bg-danger" attrs="{'invisible': [('active', '=', True)]}"/>\n                        <group class="o_mass_mailing_mailing_group">\n                            <field name="active" invisible="1"/>\n                            <field name="mailing_type" widget="radio" options="{'horizontal': true}" invisible="1" attrs="{'readonly': [('state', '!=', 'draft')]}" force_save="1"/>\n                            <label for="subject">Subject</label>\n                            <div class="o_mass_mailing_subject d-flex flex-row align-items-baseline">\n                                <field class="text-break" name="subject" string="Subject" options="{'dynamic_placeholder': true}" attrs="{'readonly': [('state', 'in', ('sending', 'done'))]}" widget="char_emojis" placeholder="e.g. New Sale on all T-shirts"/>\n                                <field name="favorite" invisible="1"/>\n                                <button type="object" name="action_set_favorite" class="o_mass_mailing_favorite p-0" icon="fa-star-o" attrs="{'invisible': [('favorite', '=', True)]}" title="Add to Templates"/>\n                                <button type="object" name="action_remove_favorite" class="o_mass_mailing_favorite p-0" icon="fa-star" attrs="{'invisible': [('favorite', '=', False)]}" title="Remove from Templates"/>\n                            </div>\n                            <label for="mailing_model_id" string="Recipients"/>\n                            <div name="mailing_model_id_container">\n                                <div class="d-flex align-items-baseline flex-wrap">\n                                    <div class="me-5">\n                                        <field name="mailing_model_id" options="{'no_open': True, 'no_create': True}" attrs="{'readonly': [('state', 'in', ('sending', 'done'))]}"/>\n                                    </div>\n                                    <div attrs="{'invisible': [('mailing_model_name', '!=', 'mailing.list')]}" class="o_mass_mailing_contact_list_ids pt-1 pt-sm-0">\n                                        <label for="contact_list_ids" string="Select mailing lists:" class="oe_edit_only pe-2"/>\n                                        <div class="d-inline-flex flex-row align-items-center">\n                                            <field name="contact_list_ids" widget="many2many_tags" placeholder="Select mailing lists..." class="oe_inline mb-0" context="{'form_view_ref': 'mass_mailing.mailing_list_view_form_simplified'}" attrs="{                                                     'required':[('mailing_model_name','=','mailing.list')],                                                     'readonly': [('state', 'in', ('sending', 'done'))]                                             }"/>\n                                            <button icon="fa-user-plus" type="object" class="btn btn-secondary py-0 px-1 ms-1" attrs="{'invisible': ['|', '|', ('contact_list_ids', '=', False), ('contact_list_ids', '=', []), ('state', 'in', ('sending', 'done'))]}" name="action_view_mailing_contacts" title="Add Mailing Contacts"/>\n                                        </div>\n                                    </div>\n                                    <div attrs="{'invisible': [('mailing_model_name', '=', 'mailing.list')]}" class="o_td_label">\n                                        <!-- We don't want to display label in edit mode, unless mailing is in sending or done state (where filter will be readonly) -->\n                                        <label for="mailing_filter_id" string="Filter" class="oe_read_only me-4" attrs="{'invisible': ['|', ('state', 'in', ('sending', 'done')), ('mailing_filter_id', '=', False)]}"/>\n                                        <label for="mailing_filter_id" string="Filter" class="me-4" attrs="{'invisible': ['|', ('state', 'not in', ('sending', 'done')), ('mailing_filter_id', '=', False)]}"/>\n                                        <field name="mailing_filter_id" placeholder="Reload a favorite filter" class="w-auto" widget="mailing_filter" options="{'no_create': 1, 'no_open': 1, 'domain_field': 'mailing_domain', 'model_field': 'mailing_model_id'}" attrs="{'readonly': [('state', 'in', ('sending', 'done'))]}"/>\n                                    </div>\n                                    <field name="mailing_filter_count" invisible="1"/>\n                                    <field name="mailing_filter_domain" invisible="1"/>\n                                </div>\n\n                                <field name="mailing_model_name" invisible="1"/>\n                                <field name="mailing_model_real" invisible="1"/>\n                                <div class="w-lg-50" attrs="{'invisible': [('mailing_model_name', '=', 'mailing.list')]}">\n                                    <field name="mailing_domain" widget="domain" options="{'model': 'mailing_model_real'}" attrs="{'readonly': [('state', 'in', ('sending', 'done'))]}"/>\n                                </div>\n                            </div>\n                        </group>\n                        <notebook>\n                            <page string="Mail Body" name="mail_body">\n                                <div class="position-relative">\n                                    <div class="mt-n2">\n                                        <field name="body_arch" class="o_mail_body" widget="mass_mailing_html" options="{                                                 'snippets': 'mass_mailing.email_designer_snippets',                                                 'cssEdit': 'mass_mailing.iframe_css_assets_edit',                                                 'inline-field': 'body_html',                                                 'dynamic_placeholder': true,                                                 'cssReadonly': 'mass_mailing.iframe_css_assets_edit'                                         }" attrs="{'readonly': [('state', 'in', ('sending', 'done'))]}"/>\n                                    </div>\n                                    <field name="is_body_empty" invisible="1"/>\n                                    <div class="o_view_nocontent oe_read_only" attrs="{'invisible': ['|', ('is_body_empty', '=', False), ('state', 'in', ('sending', 'done'))]}">\n                                        <div class="o_nocontent_help">\n                                            <p class="o_view_nocontent_smiling_face">\n                                                This mailing has no selected design (yet!).\n                                            </p>\n                                        </div>\n                                    </div>\n                                </div>\n                            </page>\n                            <page string="A/B Tests" name="ab_testing">\n                                <group>\n                                    <group>\n                                        <label for="ab_testing_enabled"/>\n                                        <span class="d-flex">\n                                            <field name="ab_testing_enabled" attrs="{'readonly': [('state', '!=', 'draft')]}" force_save="1"/>\n                                            <span class="d-flex" attrs="{'invisible': [('ab_testing_enabled', '=', False)]}">\n                                                on <field name="ab_testing_pc" class="mx-1 text-center" attrs="{'readonly': [('state', '!=', 'draft')]}"/> %\n                                            </span>\n                                        </span>\n                                        <field name="ab_testing_winner_selection" attrs="{'required': [('ab_testing_enabled', '=', True), ('mailing_type', '=', 'mail')], 'invisible': ['|', ('ab_testing_enabled', '=', False), ('mailing_type', '!=', 'mail')], 'readonly': [('state', '!=', 'draft')]}"/>\n                                        <field name="ab_testing_schedule_datetime" attrs="{'required': [('ab_testing_enabled', '=', True), ('ab_testing_winner_selection', '!=', 'manual')], 'readonly': ['|', ('ab_testing_enabled', '=', False), ('state', '!=', 'draft')], 'invisible': ['|', ('ab_testing_enabled', '=', False), ('ab_testing_winner_selection', '=', 'manual')]}"/>\n                                    </group>\n                                    <div>\n                                        <field name="ab_testing_mailings_count" invisible="1"/>\n                                        <field name="ab_testing_completed" invisible="1"/>\n                                        <field name="ab_testing_description" nolabel="1"/>\n                                        <div attrs="{'invisible': ['|', ('ab_testing_mailings_count', '&lt;', 2), ('ab_testing_enabled', '=', False)]}">\n                                            <button name="action_compare_versions" type="object" class="btn btn-link d-block">\n                                                <i class="fa fa-bar-chart"/> Compare Version\n                                            </button>\n                                            <button name="action_dup